/* Ngữ pháp từng bài (cơ bản → nâng cao), sinh từ hoc/tools/ngu-phap/tmns.js bằng hoc/tools/build_grammar.js — sửa ở file nguồn rồi chạy lại. */
HOC.gram('tmns', [{"n":1,"i":1,"t":{"id":"tmns1-np","title":"语法 · 甚至 · 如果 · 以至 · 相反 …","kind":"语法","intro":"Môn nghe nói tập trung vào **từ nối khi nói** (甚至、以至于、相反…). Những mẫu đã học ở môn Viết hoặc Đọc thương mại có dấu ↪, bấm để xem lại.","gp":[{"id":"shenzhi","lv":1,"h":"……，甚至……","g":"…, thậm chí…","s":"A **，甚至** + B (mức cao hơn, bất ngờ hơn)\n**甚至（于）** + danh từ / động từ / mệnh đề","m":"**甚至** đưa ra **ví dụ cực điểm**, nâng mức độ lên cao hơn điều vừa nói, làm người nghe bất ngờ. Đứng trước thành phần được nhấn mạnh; hay đi với 都 / 也: 甚至连……都…….","u":"Kể chuyện doanh nhân, mô tả mức độ: **他们家很穷，甚至二十岁了还没有一双鞋**; báo cáo: **销量翻了一番，甚至两番**.","e":[["这种产品很受欢迎，甚至在国外也卖得很好。","Sản phẩm này rất được ưa chuộng, thậm chí ở nước ngoài cũng bán chạy."],["很多员工甚至连周末都在加班。","Nhiều nhân viên thậm chí cả cuối tuần cũng tăng ca."]],"x":[["他很忙，甚至吃饭。","他很忙，甚至连吃饭的时间都没有。","Vế sau 甚至 phải là mức **cao hơn** cùng chiều với vế trước."]],"c":"Tăng tiến: 不仅……而且 (HNTM viết bài 25) → 甚至 (đỉnh điểm) → 以至于 (đến nỗi, kết quả).","b":["他不愿意让学生们知道自己已经改行，甚至不愿意和他们见面。","刘永好刚刚开始改行的时候，他不愿意让学生们知道自己已经改行，甚至不愿意和他们见面。"]},{"ref":"jiashe","lv":1,"h":"Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么……","g":"nếu… thì…","s":"如果 / 要是 / 假如 / 倘若 + giả thiết （的话），（那么） + chủ ngữ + 就 / 便 / 会 + kết quả","b":["如果一个人只把赚钱当作他追求的惟一目标，那么他就是最可悲的人。","如果有一天您忽然一分钱都没有了，您准备做什么？"],"home":{"s":"dtm","t":"dtm2-np","n":2,"name":"Đọc thương mại"}},{"id":"yizhiyu","lv":2,"h":"……，以至（于）……","g":"…, đến nỗi…","s":"A (mức độ cao) **，以至（于）** + B (kết quả do A gây ra)","m":"**以至于** nối nguyên nhân có **mức độ cao** với **kết quả** của nó (thường ngoài ý muốn). Khác 甚至: 甚至 tăng mức cùng loại, 以至于 nói **hệ quả**. Văn viết, dùng nhiều trong kể chuyện, bình luận.","u":"Kể đời doanh nhân: **当时他们太穷了，以至于连孵小鸡的本钱都要借**; bình luận: **市场变化太快，以至于很多企业来不及调整**.","e":[["订单太多了，以至于工厂要三班倒。","Đơn hàng nhiều đến nỗi nhà máy phải làm ba ca."],["他工作太投入了，以至于忘了吃饭。","Anh ấy say mê công việc đến nỗi quên cả ăn."]],"x":[["他很努力，以至于他成功了。","他很努力，所以成功了。 / 他太努力了，以至于累病了。","**以至于** cần vế trước nhấn **mức độ** (太、那么) và kết quả thường ngoài mong đợi; nhân quả thông thường dùng 所以."]],"c":"Phân biệt: 以至 (đến nỗi) – 以致 (dẫn đến điều xấu, văn viết) – 以至于 + kết quả.","b":["小时候他的家里非常贫穷，以至于他在20岁之前没穿过鞋子。","小时候家里非常贫穷，以至于他在20岁之前没穿过鞋子。"]},{"id":"xiangfan","lv":2,"h":"……，相反，……","g":"ngược lại…","s":"A (phủ định / một chiều) **。相反，** + B (chiều ngược lại)\n**与……相反**：trái với…","m":"**相反** đứng **đầu câu** (có dấu phẩy) để nêu điều **trái ngược** với điều vừa nói hoặc với dự đoán. Vế trước thường phủ định: 不但没有A，相反B. **与……相反** = trái với….","u":"Lập luận, kể chuyện: **困难没有吓倒他们，相反，他们越干越有劲**; phân tích thị trường: **与人们的预测相反，房价没有下跌**.","e":[["降价并没有带来利润，相反，公司亏损更严重了。","Giảm giá không đem lại lợi nhuận, ngược lại công ty lỗ nặng hơn."],["与专家的预测相反，今年的出口大幅增长。","Trái với dự báo của chuyên gia, xuất khẩu năm nay tăng mạnh."]],"x":[["他很有钱，相反他很节约。","他很有钱，可是很节约。","Hai việc không đối lập trực tiếp thì dùng 可是; **相反** dùng khi B trái hẳn với A hoặc với dự đoán."]],"c":"Gần nghĩa: 反而 (phó từ, Nghe nói bài 4) – đứng sau chủ ngữ: 他反而更努力了.","b":["90年代中期，很多人都感到房地产这碗饭是越来越难吃了，相反，刘永好却意识到机会的存在。","20世纪90年代中期，很多人都感到房地产这碗饭是越来越难吃了，相反，刘永好却意识到机会的存在。"]},{"id":"dapo","lv":2,"h":"打破……的垄断 / 记录 / 僵局","g":"phá vỡ thế độc quyền / kỷ lục / bế tắc","s":"**打破** + 垄断 / 记录 / 僵局 / 传统 / 平衡","m":"**打破** (phá vỡ) là động từ – bổ ngữ kết quả, kết hợp với các danh từ trừu tượng chỉ **tình trạng cũ bị thay đổi**. Thường đi với **的** + danh từ: 打破了国有企业的垄断.","u":"Kể chuyện doanh nghiệp tư nhân: **希望集团打破了外资企业对饲料市场的垄断**; đàm phán: **打破僵局** (phá thế bế tắc).","e":[["这家民营企业打破了国外品牌的垄断。","Doanh nghiệp tư nhân này phá vỡ thế độc quyền của các thương hiệu nước ngoài."],["双方都做了让步，终于打破了谈判的僵局。","Hai bên đều nhượng bộ, cuối cùng phá được thế bế tắc trong đàm phán."]],"x":[["他们打开了垄断。","他们打破了垄断。","打开 = mở (cửa, thị trường); 垄断 đi với **打破**."]],"c":"Kết hợp tương tự: 打开市场 (mở thị trường), 打下基础 (đặt nền móng), 打出品牌.","b":["产品质量不比进口饲料差，价格却便宜得多，公司又在全国城乡进行了广泛的宣传，“希望”饲料很快就打开了市场，打破了外国企业对中国高档饲料市场的垄断。"]},{"ref":"ji_yiti","lv":3,"h":"集A、B、C于一身 / 为一体","g":"hội tụ A, B, C trong một","s":"集 + các yếu tố + 于一身 / 为一体","b":["新希望集团终于发展成为一个集农业、房地产、金融为一体的大型企业集团。"],"home":{"s":"hntm","t":"tm7-np","n":7,"name":"HNTM viết"}}],"zh":["这种产品很受欢迎，甚至在国外也卖得很好。","很多员工甚至连周末都在加班。","他不愿意让学生们知道自己已经改行，甚至不愿意和他们见面。","刘永好刚刚开始改行的时候，他不愿意让学生们知道自己已经改行，甚至不愿意和他们见面。","订单太多了，以至于工厂要三班倒。","他工作太投入了，以至于忘了吃饭。","小时候他的家里非常贫穷，以至于他在20岁之前没穿过鞋子。","小时候家里非常贫穷，以至于他在20岁之前没穿过鞋子。","降价并没有带来利润，相反，公司亏损更严重了。","与专家的预测相反，今年的出口大幅增长。","90年代中期，很多人都感到房地产这碗饭是越来越难吃了，相反，刘永好却意识到机会的存在。","20世纪90年代中期，很多人都感到房地产这碗饭是越来越难吃了，相反，刘永好却意识到机会的存在。","如果一个人只把赚钱当作他追求的惟一目标，那么他就是最可悲的人。","如果有一天您忽然一分钱都没有了，您准备做什么？","新希望集团终于发展成为一个集农业、房地产、金融为一体的大型企业集团。","这家民营企业打破了国外品牌的垄断。","双方都做了让步，终于打破了谈判的僵局。","产品质量不比进口饲料差，价格却便宜得多，公司又在全国城乡进行了广泛的宣传，“希望”饲料很快就打开了市场，打破了外国企业对中国高档饲料市场的垄断。"],"p":["## ……，甚至…… — …, thậm chí…","## Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么…… — nếu… thì…","## ……，以至（于）…… — …, đến nỗi…","## ……，相反，…… — ngược lại…","## 打破……的垄断 / 记录 / 僵局 — phá vỡ thế độc quyền / kỷ lục / bế tắc","## 集A、B、C于一身 / 为一体 — hội tụ A, B, C trong một"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (甚至 · 以至于 · 相反 · 如果 · 集 · 打破)","items":[["这种产品很受欢迎，___在国外也卖得很好。","甚至"],["订单太多了，___工厂要三班倒。","以至于"],["降价并没有带来利润，___，公司亏损更严重了。","相反"],["___一个人只把赚钱当作他追求的惟一目标，那么他就是最可悲的人。","如果"],["新希望___团终于发展成为一个集农业、房地产、金融为一体的大型企业集团。","集"],["这家民营企业___了国外品牌的垄断。","打破"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （……，甚至……）",["他很忙，甚至吃饭。","他很忙，甚至连吃饭的时间都没有。"],1],["Câu nào đúng? （……，以至（于）……）",["他很努力，所以成功了。 / 他太努力了，以至于累病了。","他很努力，以至于他成功了。"],0],["Câu nào đúng? （……，相反，……）",["他很有钱，相反他很节约。","他很有钱，可是很节约。"],1],["Câu nào đúng? （打破……的垄断 / 记录 / 僵局）",["他们打破了垄断。","他们打开了垄断。"],0]]}],"adv":{"g":[["……，甚至……","…, thậm chí…","他不愿意让学生们知道自己已经改行，甚至不愿意和他们见面。"],["Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么……","nếu… thì…","如果一个人只把赚钱当作他追求的惟一目标，那么他就是最可悲的人。"],["……，以至（于）……","…, đến nỗi…","小时候他的家里非常贫穷，以至于他在20岁之前没穿过鞋子。"],["……，相反，……","ngược lại…","90年代中期，很多人都感到房地产这碗饭是越来越难吃了，相反，刘永好却意识到机会的存在。"],["打破……的垄断 / 记录 / 僵局","phá vỡ thế độc quyền / kỷ lục / bế tắc","产品质量不比进口饲料差，价格却便宜得多，公司又在全国城乡进行了广泛的宣传，“希望”饲料很快就打开了市场，打破了外国企业对中国高档饲料市场的垄断。"],["集A、B、C于一身 / 为一体","hội tụ A, B, C trong một","新希望集团终于发展成为一个集农业、房地产、金融为一体的大型企业集团。"]]}}},{"n":2,"i":1,"t":{"id":"tmns2-np","title":"语法 · 不是……，而是 · 虽然……但是 · 把……当 · 与……相比 …","kind":"语法","gp":[{"ref":"bushi_ershi","lv":1,"h":"不是……，而是……","g":"không phải… mà là…","s":"（主语）+ 不是 + A ，而是 + B\n变体: ……，而不是…… (Nghe nói bài 4)","b":["我去外企不是为了钱，而是想换一种方式生活。","我觉得，跳槽最重要的意义并不是追求高薪或者高一级的职位，而是重新设定事业的发展目标，让职业生涯步入更高的阶段。"],"home":{"s":"dtm","t":"dtm9-np","n":9,"name":"Đọc thương mại"}},{"ref":"zhuanzhe","lv":1,"h":"Câu chuyển ngoặt: 虽然……但是 / 可是 / 却 / 然而","g":"tuy… nhưng…","s":"虽然 / 虽 / 尽管 + A ，但是 / 可是 / 然而 / 不过 + （chủ ngữ）+ 却 / 也 / 还 + B","b":["在外企工作虽然忙，工作节奏很快，但是生活很新鲜、很丰富，可以与各种不同的人交往。"],"home":{"s":"dtm","t":"dtm7-np","n":7,"name":"Đọc thương mại"}},{"id":"ba_dang","lv":2,"h":"把……当（作）……","g":"coi… là…","s":"主语 + **把** + A + **当（作）/ 看作 / 当成** + B","m":"Câu 把 hai tân ngữ chỉ **cách nhìn nhận**: coi A như B. Rất hay dùng khi nói về **thái độ với công việc, khách hàng**. Trong khẩu ngữ, 当 là đủ; văn viết dùng 看作 / 视为.","u":"Bàn về nhảy việc: **有的人把工作当作谋生的手段，有的人把工作当成事业**.","e":[["他把公司当成自己的家。","Anh ấy coi công ty như nhà mình."],["不要把跳槽当作解决问题的唯一办法。","Đừng coi nhảy việc là cách duy nhất để giải quyết vấn đề."]],"x":[["他当公司自己的家。","他把公司当成自己的家。","Cần **把** để đưa A lên trước."]],"c":"Xem câu 把 (Đọc TM bài 4) và 把……成/作/为 (Đọc TM bài 10).","b":["如果你的上司知道你在来他的公司之前，曾经跳过七八次槽，他会很自然地得出结论：你在这儿工作也是暂时的，是把他的公司当跳板，这样你的上司还会信任你吗？"]},{"id":"yu_xiangtong","lv":2,"h":"与……相比 / 大相径庭 / 相同","g":"so với… / khác hẳn… / giống…","s":"**与 / 跟 / 和** + B + **相比，** A……\nA + **与** + B + **大相径庭 / 截然不同 / 相同 / 一致**","m":"**与** = 跟 / 和 (văn viết). **与……相比** đặt đầu câu để so sánh. **大相径庭** (thành ngữ) = khác nhau rất xa; **截然不同** = hoàn toàn khác. Đối tượng so sánh đặt sau 与.","u":"Bàn quan điểm khác nhau: **他的看法与我大相径庭**; **与去年相比，今年的跳槽率明显下降**.","e":[["与去年同期相比，出口额增长了百分之十二。","So với cùng kỳ năm ngoái, kim ngạch xuất khẩu tăng 12%."],["年轻人对跳槽的看法与父母大相径庭。","Quan điểm về nhảy việc của người trẻ khác hẳn bố mẹ."]],"x":[["他的看法大相径庭我的看法。","他的看法与我的看法大相径庭。","大相径庭 không mang tân ngữ; đối tượng đặt sau **与**."]],"c":"Văn viết: 相比之下 / 相比较之下 (so ra thì): 相比较之下，第二种方案更好."},{"ref":"buyi","lv":2,"h":"不宜……","g":"không nên…","s":"主语 + （目前 / 暂）不宜 + động từ","b":["我不反对跳槽，但我觉得跳槽不宜太频繁。"],"home":{"s":"hntm","t":"tm27-np","n":27,"name":"HNTM viết"}},{"id":"feidan","lv":3,"h":"非但不……，反而 / 还……","g":"chẳng những không… mà còn (ngược lại)…","s":"（主语）+ **非但 / 不但 / 不仅** + **不 / 没（有）** + A **，反而 / 还 / 而且** + B (ngược chiều mong đợi)","m":"Câu **tăng tiến ngược chiều**: điều mong đợi (A) không xảy ra, mà còn xảy ra điều **trái lại** (B). **非但** văn viết. Vế sau với **反而** nhấn mạnh sự trái ngược mạnh nhất; với **还 / 而且** chỉ tăng tiến.","u":"Bàn về nhảy việc: **频繁跳槽非但不能提高收入，还会影响个人信誉**; Nghe nói bài 5: **不仅不……，而且……**.","e":[["频繁跳槽非但不能积累经验，还会给人不稳定的印象。","Nhảy việc liên tục chẳng những không tích lũy được kinh nghiệm mà còn tạo ấn tượng thiếu ổn định."],["降价以后，销量不但没有增加，反而下降了。","Sau khi giảm giá, doanh số chẳng những không tăng mà ngược lại còn giảm."]],"x":[["销量不但没有增加，而且增加了。","销量不但没有增加，反而减少了。","Vế sau phải **ngược chiều** với điều mong đợi."]],"c":"Xem 不仅……而且 (HNTM viết bài 25), 相反 (bài 1). Bài 4 có 不仅没有……反而 (link về đây).","b":["上海白领女性的职业流动意识与行为非但不比男性差，还明显高于男性。","上海白领女性的职业流动意识与行为非但不比男性差，还明显高于男性，女性跳槽的人数比例比男性高。"],"also":[{"s":"tmns","t":"tmns4-np","n":4,"name":"HNTM nghe nói"},{"s":"tmns","t":"tmns5-np","n":5,"name":"HNTM nghe nói"}]}],"zh":["我去外企不是为了钱，而是想换一种方式生活。","我觉得，跳槽最重要的意义并不是追求高薪或者高一级的职位，而是重新设定事业的发展目标，让职业生涯步入更高的阶段。","在外企工作虽然忙，工作节奏很快，但是生活很新鲜、很丰富，可以与各种不同的人交往。","他把公司当成自己的家。","不要把跳槽当作解决问题的唯一办法。","如果你的上司知道你在来他的公司之前，曾经跳过七八次槽，他会很自然地得出结论：你在这儿工作也是暂时的，是把他的公司当跳板，这样你的上司还会信任你吗？","频繁跳槽非但不能积累经验，还会给人不稳定的印象。","降价以后，销量不但没有增加，反而下降了。","上海白领女性的职业流动意识与行为非但不比男性差，还明显高于男性。","上海白领女性的职业流动意识与行为非但不比男性差，还明显高于男性，女性跳槽的人数比例比男性高。","与去年同期相比，出口额增长了百分之十二。","年轻人对跳槽的看法与父母大相径庭。","我不反对跳槽，但我觉得跳槽不宜太频繁。"],"p":["## 不是……，而是…… — không phải… mà là…","## Câu chuyển ngoặt: 虽然……但是 / 可是 / 却 / 然而 — tuy… nhưng…","## 把……当（作）…… — coi… là…","## 与……相比 / 大相径庭 / 相同 — so với… / khác hẳn… / giống…","## 不宜…… — không nên…","## 非但不……，反而 / 还…… — chẳng những không… mà còn (ngược lại)…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (而是 · 虽然 · 当 · 非但 · 与 · 不宜)","items":[["我去外企不是为了钱，___想换一种方式生活。","而是"],["在外企工作___忙，工作节奏很快，但是生活很新鲜、很丰富，可以与各种不同的人交往。","虽然"],["他把公司___成自己的家。","当"],["频繁跳槽___不能积累经验，还会给人不稳定的印象。","非但"],["___去年同期相比，出口额增长了百分之十二。","与"],["我不反对跳槽，但我觉得跳槽___太频繁。","不宜"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （把……当（作）……）",["他当公司自己的家。","他把公司当成自己的家。"],1],["Câu nào đúng? （非但不……，反而 / 还……）",["销量不但没有增加，反而减少了。","销量不但没有增加，而且增加了。"],0],["Câu nào đúng? （与……相比 / 大相径庭 / 相同）",["他的看法大相径庭我的看法。","他的看法与我的看法大相径庭。"],1]]}],"adv":{"g":[["不是……，而是……","không phải… mà là…","我去外企不是为了钱，而是想换一种方式生活。"],["Câu chuyển ngoặt: 虽然……但是 / 可是 / 却 / 然而","tuy… nhưng…","在外企工作虽然忙，工作节奏很快，但是生活很新鲜、很丰富，可以与各种不同的人交往。"],["把……当（作）……","coi… là…","如果你的上司知道你在来他的公司之前，曾经跳过七八次槽，他会很自然地得出结论：你在这儿工作也是暂时的，是把他的公司当跳板，这样你的上司还会信任你吗？"],["与……相比 / 大相径庭 / 相同","so với… / khác hẳn… / giống…","与去年同期相比，出口额增长了百分之十二。"],["不宜……","không nên…","我不反对跳槽，但我觉得跳槽不宜太频繁。"],["非但不……，反而 / 还……","chẳng những không… mà còn (ngược lại)…","上海白领女性的职业流动意识与行为非但不比男性差，还明显高于男性。"]]}}},{"n":3,"i":1,"t":{"id":"tmns3-np","title":"语法 · 第一……，第二……，最后 · 除了……，还 · 既……又 · 当然 …","kind":"语法","gp":[{"id":"xulie","lv":1,"h":"第一……，第二……，最后…… / 一是……，二是……","g":"thứ nhất…, thứ hai…, cuối cùng…","s":"**第一 / 首先，** …… **第二 / 其次，** …… **第三 / 再次，** …… **最后，** ……\n（Văn viết gọn）**一是……，二是……，三是……**","m":"Từ đánh dấu **tầng ý** khi trình bày, giúp người nghe theo kịp. Trong nói: 第一、第二…… hoặc 首先、其次、最后. Văn viết, báo cáo: **一是……，二是……** (Nghe nói bài 12). Không trộn hệ thống: 首先 đi với 其次, 第一 đi với 第二.","u":"Thuyết trình về quan niệm tiêu dùng, báo cáo kinh doanh: **我认为原因有三：一是价格低，二是质量好，三是服务周到**.","e":[["首先要了解市场，其次要控制成本，最后还要做好售后服务。","Trước hết phải hiểu thị trường, kế đó phải kiểm soát chi phí, cuối cùng còn phải làm tốt hậu mãi."],["成功的原因，一是产品好，二是营销得法。","Nguyên nhân thành công, một là sản phẩm tốt, hai là tiếp thị đúng cách."]],"x":[["首先要了解市场，第二要控制成本。","首先要了解市场，其次要控制成本。","Không trộn hệ 首先 với hệ 第一."]],"c":"Kết thúc bài nói: 总之 / 总而言之 (tóm lại) — xem 插说 (Đọc TM bài 9).","b":["最后，长见识了，古人说得好：“读万卷书，行万里路”嘛。","首先是长见识了，古人说得好：“读万卷书，行万里路”嘛。","第二，现在我和老伴都退休在家，儿女都已经成家立业，对我们很孝顺，也没有什么好操心的。"],"also":[{"s":"tmns","t":"tmns12-np","n":12,"name":"HNTM nghe nói"}]},{"ref":"chule","lv":1,"h":"除了……（以外），还 / 也 / 都……","g":"ngoài… ra, còn / cũng / đều…","s":"除了 + A （以外 / 之外）， + chủ ngữ + 还 / 也 + B   → bổ sung (cả A lẫn B)\n除了 + A （以外）， + chủ ngữ + 都 + …   → loại trừ (trừ A, còn lại đều…)","b":["平时我比较节省，除了必要的吃、穿、用以外，一般都不会花什么钱。"],"home":{"s":"dtm","t":"dtm1-np","n":1,"name":"Đọc thương mại"}},{"ref":"binglie","lv":1,"h":"Câu đẳng lập: 既……又 / 一边……一边 / 一方面……另一方面","g":"vừa… vừa… / mặt này… mặt khác…","s":"既 + A + 又 / 也 + B (hai đặc điểm cùng có)\n一边 + V1 + 一边 + V2 (hai hành động cùng lúc)\n一方面 + A ，（另）一方面 + B (hai mặt của vấn đề)","b":["所以，我在外面找了两份兼职工作，做家教和做推销，既可以挣些钱，又可以积累一些工作经验。"],"home":{"s":"dtm","t":"dtm3-np","n":3,"name":"Đọc thương mại"}},{"ref":"dangran","lv":1,"h":"当然","g":"dĩ nhiên, đương nhiên","s":"① 当然 + vị ngữ (khẳng định chắc chắn)\n② 句首：当然， + bổ sung / giới hạn (tất nhiên…)","b":["当然，我们也不能浪费，中华民族勤俭节约的传统美德是不能够抛弃的。","当然有，不过比起工作压力来，经济压力就不算什么了。"],"home":{"s":"dtm","t":"dtm4-np","n":4,"name":"Đọc thương mại"}},{"id":"guang_jiu","lv":2,"h":"光……就……","g":"chỉ riêng… đã…","s":"**光（是）/ 单（是）/ 仅（仅）** + một phần + **就** + con số / mức độ lớn","m":"Nêu **một bộ phận** để làm nổi bật **tổng thể còn lớn hơn nhiều**: “chỉ riêng tiền thuê nhà đã hết một nửa lương” → tổng chi tiêu còn nhiều hơn. **光** khẩu ngữ; **单是 / 仅** văn viết hơn.","u":"Nói về chi tiêu: **光房租就占了收入的一半**; báo cáo: **仅今年上半年，出口就增长了二十个百分点**.","e":[["光广告费一年就花了五百万。","Chỉ riêng phí quảng cáo một năm đã tốn năm triệu."],["仅这一个项目，就为公司带来了上亿元的利润。","Chỉ riêng dự án này đã đem lại cho công ty hơn trăm triệu tệ lợi nhuận."]],"x":[["光房租花了很多钱。","光房租就花了很多钱。","Thiếu **就** hô ứng."]],"c":"Phân biệt 光 (chỉ riêng, khẩu ngữ) với 光 (ánh sáng; hết sạch: 花光了).","b":["我看好了亚运村的一套房子，离我的单位很近，上班方便，旁边就是奥林匹克体育中心，以后锻炼身体也很方便。"]},{"ref":"dao","lv":2,"h":"倒（是）","g":"thì lại, nhưng mà lại… (ngoài dự đoán)","s":"（虽然）A ， 主语 + 倒（是） + B (thường tích cực)\n倒 + 是 + 形容词 ，就是 / 不过 + điểm trừ","b":[],"home":{"s":"dtm","t":"dtm1-np","n":1,"name":"Đọc thương mại"}}],"zh":["首先要了解市场，其次要控制成本，最后还要做好售后服务。","成功的原因，一是产品好，二是营销得法。","最后，长见识了，古人说得好：“读万卷书，行万里路”嘛。","首先是长见识了，古人说得好：“读万卷书，行万里路”嘛。","第二，现在我和老伴都退休在家，儿女都已经成家立业，对我们很孝顺，也没有什么好操心的。","光广告费一年就花了五百万。","仅这一个项目，就为公司带来了上亿元的利润。","我看好了亚运村的一套房子，离我的单位很近，上班方便，旁边就是奥林匹克体育中心，以后锻炼身体也很方便。","平时我比较节省，除了必要的吃、穿、用以外，一般都不会花什么钱。","所以，我在外面找了两份兼职工作，做家教和做推销，既可以挣些钱，又可以积累一些工作经验。","当然，我们也不能浪费，中华民族勤俭节约的传统美德是不能够抛弃的。","当然有，不过比起工作压力来，经济压力就不算什么了。"],"p":["## 第一……，第二……，最后…… / 一是……，二是…… — thứ nhất…, thứ hai…, cuối cùng…","## 除了……（以外），还 / 也 / 都…… — ngoài… ra, còn / cũng / đều…","## Câu đẳng lập: 既……又 / 一边……一边 / 一方面……另一方面 — vừa… vừa… / mặt này… mặt khác…","## 当然 — dĩ nhiên, đương nhiên","## 光……就…… — chỉ riêng… đã…","## 倒（是） — thì lại, nhưng mà lại… (ngoài dự đoán)"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (首先 · 光 · 除了 · 既 · 当然)","items":[["___要了解市场，其次要控制成本，最后还要做好售后服务。","首先"],["___广告费一年就花了五百万。","光"],["平时我比较节省，___必要的吃、穿、用以外，一般都不会花什么钱。","除了"],["所以，我在外面找了两份兼职工作，做家教和做推销，___可以挣些钱，又可以积累一些工作经验。","既"],["___，我们也不能浪费，中华民族勤俭节约的传统美德是不能够抛弃的。","当然"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （第一……，第二……，最后…… / 一是……，二是……）",["首先要了解市场，第二要控制成本。","首先要了解市场，其次要控制成本。"],1],["Câu nào đúng? （光……就……）",["光房租就花了很多钱。","光房租花了很多钱。"],0]]}],"adv":{"g":[["第一……，第二……，最后…… / 一是……，二是……","thứ nhất…, thứ hai…, cuối cùng…","最后，长见识了，古人说得好：“读万卷书，行万里路”嘛。"],["除了……（以外），还 / 也 / 都……","ngoài… ra, còn / cũng / đều…","平时我比较节省，除了必要的吃、穿、用以外，一般都不会花什么钱。"],["Câu đẳng lập: 既……又 / 一边……一边 / 一方面……另一方面","vừa… vừa… / mặt này… mặt khác…","所以，我在外面找了两份兼职工作，做家教和做推销，既可以挣些钱，又可以积累一些工作经验。"],["当然","dĩ nhiên, đương nhiên","当然，我们也不能浪费，中华民族勤俭节约的传统美德是不能够抛弃的。"],["光……就……","chỉ riêng… đã…","我看好了亚运村的一套房子，离我的单位很近，上班方便，旁边就是奥林匹克体育中心，以后锻炼身体也很方便。"],["倒（是）","thì lại, nhưng mà lại… (ngoài dự đoán)",""]]}}},{"n":4,"i":1,"t":{"id":"tmns4-np","title":"语法 · 不是……，而是 · 之所以……，是因为 · 观点 — 例子 — 结论 · 不仅没有……，反而 …","kind":"语法","gp":[{"ref":"bushi_ershi","lv":1,"h":"不是……，而是……","g":"không phải… mà là…","s":"（主语）+ 不是 + A ，而是 + B\n变体: ……，而不是…… (Nghe nói bài 4)","b":["调查显示，六成以上的北京人选择留在了北京，而不是再像以往那样一窝蜂地挤往外地旅游。"],"home":{"s":"dtm","t":"dtm9-np","n":9,"name":"Đọc thương mại"}},{"id":"zhisuoyi","lv":2,"h":"之所以……，是因为……","g":"sở dĩ… là vì…","s":"主语 + **之所以** + kết quả **，是因为 / 是由于** + nguyên nhân","m":"Cấu trúc **đảo nhân quả để nhấn mạnh nguyên nhân**: nêu kết quả (đã biết) trước, rồi giải thích lý do. Chủ ngữ đặt **trước** 之所以. Dùng nhiều trong phân tích, giải thích, báo cáo.","u":"Phân tích kinh tế ngày nghỉ: **黄金周之所以人多，是因为大家的假期都集中在一起**.","e":[["这家公司之所以发展得这么快，是因为它重视人才。","Công ty này sở dĩ phát triển nhanh như vậy là vì coi trọng nhân tài."],["我们之所以选择这家供应商，是因为它的交货期最短。","Chúng tôi sở dĩ chọn nhà cung cấp này là vì thời hạn giao hàng của họ ngắn nhất."]],"x":[["之所以他成功，因为他努力。","他之所以成功，是因为他努力。","Chủ ngữ đặt trước **之所以**; vế sau cần **是因为**."]],"c":"Thường: 因为……所以…… (nguyên nhân trước). Văn khen: 这要归功于 (HNTM viết bài 2).","b":["王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。"]},{"id":"juli","lv":2,"h":"Khung nói có ví dụ: 观点 — 例子 — 结论","g":"nêu ý kiến, đưa ví dụ, kết luận","s":"**我认为……** → **比如说 / 举个例子 / 就拿……来说** → **所以 / 可见 / 总之……**","m":"Khi nói một đoạn quan điểm (thi nói), dùng khung ba bước: ① nêu **quan điểm**; ② đưa **ví dụ** cụ thể với 比如说、举个例子、就拿……来说; ③ **kết luận** lại với 所以、可见 (Đọc TM bài 5)、总之. Khung này làm bài nói mạch lạc, dễ ghi điểm.","u":"Bài nói về kinh tế ngày nghỉ: **我认为黄金周有利有弊。就拿交通来说，……。所以，我建议……**.","e":[["就拿我们公司来说，黄金周的销售额占全年的百分之十五。","Lấy ngay công ty chúng tôi làm ví dụ, doanh thu tuần lễ vàng chiếm 15% cả năm."],["举个例子，去年春节期间，景区的门票收入增长了一倍。","Lấy một ví dụ, dịp Tết năm ngoái, doanh thu vé các khu du lịch tăng gấp đôi."]],"x":[["拿我们公司来说吧。所以黄金周很好。","就拿我们公司来说，……（ví dụ cụ thể）。所以，黄金周对企业很重要。","Sau 就拿……来说 phải có **ví dụ cụ thể** rồi mới kết luận."]],"c":"Liên hệ: 比如说 (bài 6), 可见 (Đọc TM bài 5)."},{"id":"fan_er","lv":3,"h":"不仅没有……，反而……","g":"chẳng những không… mà ngược lại…","s":"主语 + **不仅 / 不但 / 非但** + **没有 / 不** + A **，反而** + B","m":"**反而** là phó từ đứng **sau chủ ngữ** của vế sau, báo kết quả **trái hẳn** điều lẽ ra phải xảy ra. Điểm này là trường hợp mạnh nhất của mẫu 非但不……还 (bài 2).","u":"Bàn về “Tuần lễ vàng”: **黄金周不仅没有让人们好好休息，反而让大家更累了**.","e":[["长假不仅没有让人放松，反而让人更累了。","Kỳ nghỉ dài chẳng những không giúp người ta thư giãn, mà ngược lại còn mệt hơn."],["提价以后，顾客反而更多了。","Sau khi tăng giá, khách hàng lại còn đông hơn."]],"x":[["降价了，反而销量增加了。","降价了，销量反而下降了。","**反而** đứng **sau chủ ngữ**, và chỉ dùng khi kết quả **trái** với dự đoán (giảm giá mà doanh số tăng thì không “trái” — không dùng 反而)."]],"c":"Link: 非但不……还 (bài 2), 相反 (bài 1).","b":["王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。"]},{"ref":"feidan","lv":3,"h":"非但不……，反而 / 还……","g":"chẳng những không… mà còn (ngược lại)…","s":"（主语）+ 非但 / 不但 / 不仅 + 不 / 没（有） + A ，反而 / 还 / 而且 + B (ngược chiều mong đợi)","b":["王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。"],"home":{"s":"tmns","t":"tmns2-np","n":2,"name":"HNTM nghe nói"}}],"zh":["这家公司之所以发展得这么快，是因为它重视人才。","我们之所以选择这家供应商，是因为它的交货期最短。","王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。","长假不仅没有让人放松，反而让人更累了。","提价以后，顾客反而更多了。","就拿我们公司来说，黄金周的销售额占全年的百分之十五。","举个例子，去年春节期间，景区的门票收入增长了一倍。","调查显示，六成以上的北京人选择留在了北京，而不是再像以往那样一窝蜂地挤往外地旅游。"],"p":["## 不是……，而是…… — không phải… mà là…","## 之所以……，是因为…… — sở dĩ… là vì…","## Khung nói có ví dụ: 观点 — 例子 — 结论 — nêu ý kiến, đưa ví dụ, kết luận","## 不仅没有……，反而…… — chẳng những không… mà ngược lại…","## 非但不……，反而 / 还…… — chẳng những không… mà còn (ngược lại)…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (之所以 · 反而 · 就拿)","items":[["这家公司___发展得这么快，是因为它重视人才。","之所以"],["长假不仅没有让人放松，___让人更累了。","反而"],["___我们公司来说，黄金周的销售额占全年的百分之十五。","就拿"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （之所以……，是因为……）",["之所以他成功，因为他努力。","他之所以成功，是因为他努力。"],1],["Câu nào đúng? （不仅没有……，反而……）",["降价了，销量反而下降了。","降价了，反而销量增加了。"],0],["Câu nào đúng? （Khung nói có ví dụ: 观点 — 例子 — 结论）",["拿我们公司来说吧。所以黄金周很好。","就拿我们公司来说，……（ví dụ cụ thể）。所以，黄金周对企业很重要。"],1]]}],"adv":{"g":[["不是……，而是……","không phải… mà là…","调查显示，六成以上的北京人选择留在了北京，而不是再像以往那样一窝蜂地挤往外地旅游。"],["之所以……，是因为……","sở dĩ… là vì…","王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。"],["Khung nói có ví dụ: 观点 — 例子 — 结论","nêu ý kiến, đưa ví dụ, kết luận","就拿我们公司来说，黄金周的销售额占全年的百分之十五。"],["不仅没有……，反而……","chẳng những không… mà ngược lại…","王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。"],["非但不……，反而 / 还……","chẳng những không… mà còn (ngược lại)…","王先生说，之所以选择留京，主要是因为前几年黄金周外出旅游不仅没有达到休养身心的目的，反而弄得身心疲惫。"]]}}},{"n":5,"i":1,"t":{"id":"tmns5-np","title":"语法 · 当然 · 从而 · 此外 · 莫过于 …","kind":"语法","gp":[{"ref":"dangran","lv":1,"h":"当然","g":"dĩ nhiên, đương nhiên","s":"① 当然 + vị ngữ (khẳng định chắc chắn)\n② 句首：当然， + bổ sung / giới hạn (tất nhiên…)","b":["李泽钜和李泽楷在列席董事会时学到很多经商诀窍，当然，除此之外，他们学到更多的是勤奋、谦逊、讲信用和守诺言等做人的道理。"],"home":{"s":"dtm","t":"dtm4-np","n":4,"name":"Đọc thương mại"}},{"id":"conger","lv":2,"h":"……，从而……","g":"…, từ đó (mà)…","s":"Phương pháp / nguyên nhân A **，从而** + kết quả B (thường tích cực, cùng chủ ngữ)","m":"**从而** = do đó, nhờ thế mà (văn viết). Nối biện pháp với **kết quả đạt được**; hai vế thường **cùng chủ ngữ**, vế sau không lặp chủ ngữ. Khác 因此: 从而 nhấn vào “nhờ cách làm đó mà đạt được”.","u":"Phân tích doanh nghiệp gia đình: **他们重视家族团结，从而保证了企业的稳定发展**.","e":[["公司引进了新技术，从而大大降低了生产成本。","Công ty nhập công nghệ mới, từ đó giảm mạnh chi phí sản xuất."],["通过网上销售，企业扩大了市场，从而增加了利润。","Nhờ bán hàng trực tuyến, doanh nghiệp mở rộng thị trường, từ đó tăng lợi nhuận."]],"x":[["公司引进了新技术，从而公司降低了成本。","公司引进了新技术，从而降低了成本。","Vế sau 从而 thường **không lặp chủ ngữ**."]],"c":"Họ 而: 而 (Đọc TM bài 4), 反而 (bài 4), 进而 (tiến thêm một bước).","b":["新加坡的李光前1928年创立南益公司，只用10多年的工夫便成为新加坡及马来西亚橡胶业的风云人物，后来又与人合资创办新加坡华侨银行，从而成为金融界巨子。"]},{"ref":"ciwai","lv":2,"h":"此外 / 除此之外","g":"ngoài ra","s":"Nội dung A 。此外， + nội dung B (bổ sung)\n除此之外， + ……","b":["李泽钜和李泽楷在列席董事会时学到很多经商诀窍，当然，除此之外，他们学到更多的是勤奋、谦逊、讲信用和守诺言等做人的道理。"],"home":{"s":"dtm","t":"dtm7-np","n":7,"name":"Đọc thương mại"}},{"id":"moguoyu","lv":3,"h":"……莫过于……","g":"không gì… bằng…","s":"A（tính từ / động từ + 的）+ **莫过于** + B\n（= 没有比 B 更 A 的）","m":"**莫** = không có gì; **过** = vượt qua. **莫过于** = không gì vượt hơn → B là **cái nhất**. Cấu trúc so sánh nhất văn viết, rất trang trọng, thường dùng mở hoặc kết luận.","u":"Bàn về doanh nghiệp gia đình: **家族企业最大的危险莫过于家庭不和**.","e":[["企业最宝贵的财富莫过于人才。","Tài sản quý nhất của doanh nghiệp không gì bằng nhân tài."],["做生意最重要的莫过于诚信。","Làm ăn điều quan trọng nhất không gì bằng chữ tín."]],"x":[["人才莫过于最重要的。","最重要的莫过于人才。","Thứ tự: **thuộc tính (最……的) + 莫过于 + B**."]],"c":"So sánh nhất khác: 最……、没有比……更……的、首屈一指 (đứng đầu). Xem câu so sánh (Đọc TM bài 5).","b":["在海外华人社会中，无论是富商巨贾还是小企业主，他们最操心的莫过于自己的事业是否后继有人。"]},{"id":"buyayu","lv":3,"h":"不亚于……","g":"không kém…","s":"A + （的 + phương diện）+ **不亚于** + B","m":"**亚** = kém hơn, đứng thứ hai; **不亚于** = không thua kém. Dùng để khen A **ngang bằng hoặc hơn** B (B thường là chuẩn mực được công nhận). Văn viết.","u":"Phân tích doanh nghiệp: **这家家族企业的管理水平不亚于跨国公司**.","e":[["国产手机的质量已经不亚于进口品牌。","Chất lượng điện thoại nội địa đã không kém hàng hiệu nhập khẩu."],["其影响力不亚于一家大型国企。","Sức ảnh hưởng của nó không kém một doanh nghiệp nhà nước lớn."]],"x":[["这家公司不亚于那家公司好。","这家公司不亚于那家公司。","Sau **不亚于 + B** không thêm tính từ."]],"c":"Liên hệ: A 于 B (HNTM viết bài 19), 比 (Đọc TM bài 5).","b":["有人曾说，股份制是人类最伟大的发明之一，其对人类的贡献，不亚于蒸汽机。"]},{"ref":"feidan","lv":3,"h":"非但不……，反而 / 还……","g":"chẳng những không… mà còn (ngược lại)…","s":"（主语）+ 非但 / 不但 / 不仅 + 不 / 没（有） + A ，反而 / 还 / 而且 + B (ngược chiều mong đợi)","b":["为了具备能适应商战的健全人格和良好心理素质，父辈对子女不仅不溺爱，而且要求极严。"],"home":{"s":"tmns","t":"tmns2-np","n":2,"name":"HNTM nghe nói"}}],"zh":["公司引进了新技术，从而大大降低了生产成本。","通过网上销售，企业扩大了市场，从而增加了利润。","新加坡的李光前1928年创立南益公司，只用10多年的工夫便成为新加坡及马来西亚橡胶业的风云人物，后来又与人合资创办新加坡华侨银行，从而成为金融界巨子。","企业最宝贵的财富莫过于人才。","做生意最重要的莫过于诚信。","在海外华人社会中，无论是富商巨贾还是小企业主，他们最操心的莫过于自己的事业是否后继有人。","国产手机的质量已经不亚于进口品牌。","其影响力不亚于一家大型国企。","有人曾说，股份制是人类最伟大的发明之一，其对人类的贡献，不亚于蒸汽机。","为了具备能适应商战的健全人格和良好心理素质，父辈对子女不仅不溺爱，而且要求极严。","李泽钜和李泽楷在列席董事会时学到很多经商诀窍，当然，除此之外，他们学到更多的是勤奋、谦逊、讲信用和守诺言等做人的道理。"],"p":["## 当然 — dĩ nhiên, đương nhiên","## ……，从而…… — …, từ đó (mà)…","## 此外 / 除此之外 — ngoài ra","## ……莫过于…… — không gì… bằng…","## 不亚于…… — không kém…","## 非但不……，反而 / 还…… — chẳng những không… mà còn (ngược lại)…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (从而 · 莫过于 · 不亚于 · 当然)","items":[["公司引进了新技术，___大大降低了生产成本。","从而"],["企业最宝贵的财富___人才。","莫过于"],["国产手机的质量已经___进口品牌。","不亚于"],["李泽钜和李泽楷在列席董事会时学到很多经商诀窍，___，除此之外，他们学到更多的是勤奋、谦逊、讲信用和守诺言等做人的道理。","当然"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （……，从而……）",["公司引进了新技术，从而公司降低了成本。","公司引进了新技术，从而降低了成本。"],1],["Câu nào đúng? （……莫过于……）",["最重要的莫过于人才。","人才莫过于最重要的。"],0],["Câu nào đúng? （不亚于……）",["这家公司不亚于那家公司好。","这家公司不亚于那家公司。"],1]]}],"adv":{"g":[["当然","dĩ nhiên, đương nhiên","李泽钜和李泽楷在列席董事会时学到很多经商诀窍，当然，除此之外，他们学到更多的是勤奋、谦逊、讲信用和守诺言等做人的道理。"],["……，从而……","…, từ đó (mà)…","新加坡的李光前1928年创立南益公司，只用10多年的工夫便成为新加坡及马来西亚橡胶业的风云人物，后来又与人合资创办新加坡华侨银行，从而成为金融界巨子。"],["此外 / 除此之外","ngoài ra","李泽钜和李泽楷在列席董事会时学到很多经商诀窍，当然，除此之外，他们学到更多的是勤奋、谦逊、讲信用和守诺言等做人的道理。"],["……莫过于……","không gì… bằng…","在海外华人社会中，无论是富商巨贾还是小企业主，他们最操心的莫过于自己的事业是否后继有人。"],["不亚于……","không kém…","有人曾说，股份制是人类最伟大的发明之一，其对人类的贡献，不亚于蒸汽机。"],["非但不……，反而 / 还……","chẳng những không… mà còn (ngược lại)…","为了具备能适应商战的健全人格和良好心理素质，父辈对子女不仅不溺爱，而且要求极严。"]]}}},{"n":6,"i":1,"t":{"id":"tmns6-np","title":"语法 · 比如 · 只要……，就 · 于是 · 也许 …","kind":"语法","gp":[{"id":"biru","lv":1,"h":"比如（说）/ 例如 / 像……","g":"chẳng hạn như…","s":"Ý khái quát **，比如（说）/ 例如 / 像** + ví dụ（**等**）","m":"Đưa **ví dụ minh họa** cho ý chung. **比如说** khẩu ngữ, **例如** văn viết; **像……等** liệt kê. Đứng đầu vế sau, có thể tách bằng dấu phẩy hoặc hai chấm.","u":"Tư vấn đầu tư: **理财的方法很多，比如说买股票、买基金、买保险等**.","e":[["投资的方式很多，比如股票、债券、房地产等。","Có nhiều cách đầu tư, chẳng hạn cổ phiếu, trái phiếu, bất động sản."],["有些行业风险很大，例如期货交易。","Một số ngành rủi ro rất cao, ví dụ giao dịch hợp đồng tương lai."]],"x":[["比如说股票、基金、保险等等等。","比如说股票、基金、保险等。","Kết thúc liệt kê dùng **等** (hoặc 等等), không lặp nhiều lần."]],"c":"Khung nói có ví dụ: xem bài 4.","b":["专家建议他把钱分成三部分：一部分满足生活支出，一部分用于短期目标的支出，比如买电脑、旅游，一部分用于长期目标的支出，比如买房、孩子上学。"]},{"ref":"zhiyao","lv":1,"h":"只要……，就 / 都 / 便……","g":"chỉ cần… là…","s":"只要 + điều kiện đủ ， + chủ ngữ + 就 / 都 / 便 + kết quả","b":["但是股票和房产也并不完全是投机性的，只要把握住一定的规律，平稳投入，不要操之过急，只要相信积累就是财富，你一样可以成为百万富翁。"],"home":{"s":"dtm","t":"dtm5-np","n":5,"name":"Đọc thương mại"}},{"ref":"yushi","lv":1,"h":"于是","g":"thế là, liền","s":"Sự việc A ，于是 + (chủ ngữ) + hành động B (kết quả tự nhiên của A)","b":[],"home":{"s":"dtm","t":"dtm4-np","n":4,"name":"Đọc thương mại"}},{"ref":"yexu","lv":1,"h":"也许","g":"có lẽ","s":"也许 + vị ngữ / mệnh đề; trả lời độc lập: 也许吧","b":["一般人会说，以上两位女士的致富是运气，如果她没有买到好股和好地段的房产，也许还会血本无归呢。"],"home":{"s":"dtm","t":"dtm5-np","n":5,"name":"Đọc thương mại"}},{"ref":"fouze","lv":2,"h":"……，否则……","g":"…, nếu không thì…","s":"Yêu cầu / điều kiện ，否则 + hậu quả xấu","b":["不然的话，你有50万元的时候，同样不知道投资理财，因为你任何投资理财经验都没有。"],"home":{"s":"hntm","t":"tm24-np","n":24,"name":"HNTM viết"}},{"ref":"ze","lv":3,"h":"（如……），则……","g":"(nếu…) thì…","s":"（如 / 若 / 倘若 + điều kiện），则 + kết quả\n hoặc: A……，B 则…… (đối chiếu)","b":[],"home":{"s":"hntm","t":"tm22-np","n":22,"name":"HNTM viết"}}],"zh":["投资的方式很多，比如股票、债券、房地产等。","有些行业风险很大，例如期货交易。","专家建议他把钱分成三部分：一部分满足生活支出，一部分用于短期目标的支出，比如买电脑、旅游，一部分用于长期目标的支出，比如买房、孩子上学。","但是股票和房产也并不完全是投机性的，只要把握住一定的规律，平稳投入，不要操之过急，只要相信积累就是财富，你一样可以成为百万富翁。","不然的话，你有50万元的时候，同样不知道投资理财，因为你任何投资理财经验都没有。","一般人会说，以上两位女士的致富是运气，如果她没有买到好股和好地段的房产，也许还会血本无归呢。"],"p":["## 比如（说）/ 例如 / 像…… — chẳng hạn như…","## 只要……，就 / 都 / 便…… — chỉ cần… là…","## 于是 — thế là, liền","## 也许 — có lẽ","## ……，否则…… — …, nếu không thì…","## （如……），则…… — (nếu…) thì…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (比如 · 只要 · 也许)","items":[["投资的方式很多，___股票、债券、房地产等。","比如"],["但是股票和房产也并不完全是投机性的，___把握住一定的规律，平稳投入，不要操之过急，只要相信积累就是财富，你一样可以成为百万富翁。","只要"],["一般人会说，以上两位女士的致富是运气，如果她没有买到好股和好地段的房产，___还会血本无归呢。","也许"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （比如（说）/ 例如 / 像……）",["比如说股票、基金、保险等等等。","比如说股票、基金、保险等。"],1]]}],"adv":{"g":[["比如（说）/ 例如 / 像……","chẳng hạn như…","专家建议他把钱分成三部分：一部分满足生活支出，一部分用于短期目标的支出，比如买电脑、旅游，一部分用于长期目标的支出，比如买房、孩子上学。"],["只要……，就 / 都 / 便……","chỉ cần… là…","但是股票和房产也并不完全是投机性的，只要把握住一定的规律，平稳投入，不要操之过急，只要相信积累就是财富，你一样可以成为百万富翁。"],["于是","thế là, liền",""],["也许","có lẽ","一般人会说，以上两位女士的致富是运气，如果她没有买到好股和好地段的房产，也许还会血本无归呢。"],["……，否则……","…, nếu không thì…","不然的话，你有50万元的时候，同样不知道投资理财，因为你任何投资理财经验都没有。"],["（如……），则……","(nếu…) thì…",""]]}}},{"n":7,"i":1,"t":{"id":"tmns7-np","title":"语法 · 增长了 · 分别……和 · 截至 · 由……降至 …","kind":"语法","intro":"Bài 7 chuyên về **nói số liệu kinh tế**: tăng / giảm, chiếm tỷ lệ, xếp hạng. Đây là phần hay ra đề nghe.","gp":[{"id":"zengzhang","lv":2,"h":"Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平","g":"tăng thêm / tăng lên tới / so cùng kỳ / ngang bằng","s":"**增长 / 增加 / 上升 + 了** + phần tăng (增长了20%)\n**增长 / 增加 + 到 / 至** + con số cuối (增长到一亿)\n**比上季度 / 同比 / 环比** + 增长……\n**与……持平** (ngang bằng)\n**翻了一番** (gấp đôi)","m":"Phân biệt cốt lõi: **了** + mức tăng (thêm bao nhiêu) ≠ **到 / 至** + kết quả (lên tới bao nhiêu). **同比** = so với cùng kỳ năm trước; **环比** = so với kỳ liền trước. **翻一番** = gấp 2, **翻两番** = gấp 4 (không phải gấp 3!). Giảm: 下降了 / 下降到 / 降至.","u":"Báo cáo tài chính quý (Sohu 2002): **第三季度收入比上一季度增长了15%**; **广告收入与上季度持平**.","e":[["今年第一季度销售额同比增长了百分之十二。","Doanh số quý I năm nay tăng 12% so với cùng kỳ."],["公司员工从三百人增加到了一千人。","Nhân viên công ty tăng từ 300 người lên tới 1.000 người."]],"x":[["去年销售额是八千万，今年增长了一亿元，达到一亿元。","去年销售额是八千万，今年增长到一亿元。","Con số **cuối cùng** dùng **到**; **了** chỉ phần tăng thêm (ở đây chỉ tăng 20 triệu)."],["利润翻了两番，就是增加了两倍。","利润翻了两番，就是增加到原来的四倍。","**翻两番** = gấp 4 lần."]],"c":"Liên quan: 由……降至 (dưới), 分别占 (dưới), 截至 (HNTM viết bài 28).","b":["2002年第三季度，搜狐网络广告收入比2001年同期增长93%。","与去年同期相比，中华网今年第一季度的营业收入增长了26%，运营亏损由去年同期的880万美元下降了59%，减至370万美元。"],"also":[{"s":"tmns","t":"tmns16-np","n":16,"name":"HNTM nghe nói"}]},{"id":"fenbie","lv":2,"h":"分别（占 / 为）……和……","g":"lần lượt (chiếm / là)… và…","s":"A 和 B + **分别** + 占 / 为 / 达到 + X 和 Y\n（A ↔ X，B ↔ Y theo đúng thứ tự）","m":"**分别** = lần lượt, tương ứng theo thứ tự. Khi nêu nhiều số liệu cho nhiều đối tượng, 分别 giúp ghép đúng cặp. Nếu các số **bằng nhau** thì dùng **各** (HNTM viết bài 29).","u":"Báo cáo cơ cấu doanh thu: **广告收入和网络游戏收入分别占总收入的45%和30%**.","e":[["广告和电子商务收入分别占总收入的百分之四十和百分之二十五。","Doanh thu quảng cáo và thương mại điện tử lần lượt chiếm 40% và 25% tổng doanh thu."],["两家公司的利润分别为三千万和五千万元。","Lợi nhuận hai công ty lần lượt là 30 triệu và 50 triệu tệ."]],"x":[["两家公司各占百分之六十和百分之四十。","两家公司分别占百分之六十和百分之四十。","Tỷ lệ khác nhau phải dùng **分别**."]],"c":"分别 còn nghĩa “chia tay”, “phân biệt”: 分别了十年; 分别对待."},{"ref":"jiezhi","lv":2,"h":"截至 / 截止","g":"tính đến / hạn chót","s":"截至 + thời điểm ， + số liệu, tình hình (tính tới lúc đó)\n…… + （于） + thời điểm + 截止","b":["北京时间5月7日晚，中华网公布了其截至3月31日的2003年第一季度财务报告。","2002年10月22日，搜狐公布了截至9月30日的第三季度财务报告，在国内各大门户网站中率先宣布实现全面盈利。"],"home":{"s":"hntm","t":"tm28-np","n":28,"name":"HNTM viết"}},{"id":"youzhi","lv":3,"h":"由……降至 / 升至……","g":"giảm từ… xuống… / tăng từ… lên…","s":"（指标）+ **由 / 从** + số đầu + **降至 / 降到 / 升至 / 增至** + số cuối","m":"Văn viết báo cáo dùng **由** (= 从, từ) và **至** (= 到, đến). Mô tả **biến động hai đầu**: điểm xuất phát và điểm kết thúc. **降至** = giảm xuống còn; **增至 / 升至** = tăng lên đến.","u":"Báo cáo: **亏损由上一季度的200万美元降至50万美元**; **失业率由5%升至6.2%**.","e":[["公司的亏损由去年的五百万降至一百万。","Khoản lỗ của công ty giảm từ 5 triệu năm ngoái xuống 1 triệu."],["市场份额由百分之八升至百分之十二。","Thị phần tăng từ 8% lên 12%."]],"x":[["亏损由五百万降至了一百万了。","亏损由五百万降至一百万。","Văn báo cáo gọn: bỏ 了 thừa."]],"c":"Xem 增长了 / 增长到 (trên), 由 (HNTM viết bài 21 – nghĩa “từ”)."},{"id":"jizhihou","lv":3,"h":"继……之后，又……","g":"tiếp sau…, lại…","s":"**继** + sự kiện / người trước + **之后，** + chủ ngữ + **又** + sự kiện mới","m":"**继** = tiếp theo; **之后** = sau. Nêu **chuỗi thành tích nối tiếp**: sau một sự kiện đã có, lại thêm một sự kiện tương tự. Văn viết, hay dùng trong tin tức kinh tế.","u":"Tin tức: **继第二季度首次盈利之后，搜狐第三季度又一次实现盈利**.","e":[["继去年在上海设厂之后，公司今年又在越南建了新厂。","Tiếp sau việc mở nhà máy ở Thượng Hải năm ngoái, năm nay công ty lại xây nhà máy mới ở Việt Nam."],["继苹果之后，又一家科技公司市值突破万亿美元。","Tiếp sau Apple, lại một công ty công nghệ nữa có vốn hóa vượt nghìn tỷ USD."]],"x":[["继去年盈利之后，今年盈利了。","继去年盈利之后，今年又实现了盈利。","Vế sau cần **又** để nhấn mạnh “lại lần nữa”."]],"c":"Tương tự: 自……以来 (kể từ…), 在……之后."},{"ref":"fanwen","lv":3,"h":"Câu hỏi tu từ (反问句)","g":"hỏi để khẳng định / phủ định mạnh","s":"不是……吗？ = khẳng định (不是说好了吗？= đã nói rồi mà)\n难道……吗？ = phủ định mạnh (难道你不知道吗？= lẽ nào anh không biết)\n怎么 / 哪儿 / 谁 + 能……？ = không thể (哪儿能这么便宜？)\n何必……？ = không cần","b":[],"home":{"s":"dtm","t":"dtm6-np","n":6,"name":"Đọc thương mại"}}],"zh":["今年第一季度销售额同比增长了百分之十二。","公司员工从三百人增加到了一千人。","2002年第三季度，搜狐网络广告收入比2001年同期增长93%。","与去年同期相比，中华网今年第一季度的营业收入增长了26%，运营亏损由去年同期的880万美元下降了59%，减至370万美元。","广告和电子商务收入分别占总收入的百分之四十和百分之二十五。","两家公司的利润分别为三千万和五千万元。","公司的亏损由去年的五百万降至一百万。","市场份额由百分之八升至百分之十二。","继去年在上海设厂之后，公司今年又在越南建了新厂。","继苹果之后，又一家科技公司市值突破万亿美元。","北京时间5月7日晚，中华网公布了其截至3月31日的2003年第一季度财务报告。","2002年10月22日，搜狐公布了截至9月30日的第三季度财务报告，在国内各大门户网站中率先宣布实现全面盈利。"],"p":["## Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平 — tăng thêm / tăng lên tới / so cùng kỳ / ngang bằng","## 分别（占 / 为）……和…… — lần lượt (chiếm / là)… và…","## 截至 / 截止 — tính đến / hạn chót","## 由……降至 / 升至…… — giảm từ… xuống… / tăng từ… lên…","## 继……之后，又…… — tiếp sau…, lại…","## Câu hỏi tu từ (反问句) — hỏi để khẳng định / phủ định mạnh"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (分别 · 降至 · 继)","items":[["广告和电子商务收入___占总收入的百分之四十和百分之二十五。","分别"],["公司的亏损由去年的五百万___一百万。","降至"],["___去年在上海设厂之后，公司今年又在越南建了新厂。","继"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平）",["去年销售额是八千万，今年增长了一亿元，达到一亿元。","去年销售额是八千万，今年增长到一亿元。"],1],["Câu nào đúng? （Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平）",["利润翻了两番，就是增加到原来的四倍。","利润翻了两番，就是增加了两倍。"],0],["Câu nào đúng? （分别（占 / 为）……和……）",["两家公司各占百分之六十和百分之四十。","两家公司分别占百分之六十和百分之四十。"],1],["Câu nào đúng? （由……降至 / 升至……）",["亏损由五百万降至一百万。","亏损由五百万降至了一百万了。"],0],["Câu nào đúng? （继……之后，又……）",["继去年盈利之后，今年盈利了。","继去年盈利之后，今年又实现了盈利。"],1]]}],"adv":{"g":[["Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平","tăng thêm / tăng lên tới / so cùng kỳ / ngang bằng","2002年第三季度，搜狐网络广告收入比2001年同期增长93%。"],["分别（占 / 为）……和……","lần lượt (chiếm / là)… và…","广告和电子商务收入分别占总收入的百分之四十和百分之二十五。"],["截至 / 截止","tính đến / hạn chót","北京时间5月7日晚，中华网公布了其截至3月31日的2003年第一季度财务报告。"],["由……降至 / 升至……","giảm từ… xuống… / tăng từ… lên…","公司的亏损由去年的五百万降至一百万。"],["继……之后，又……","tiếp sau…, lại…","继去年在上海设厂之后，公司今年又在越南建了新厂。"],["Câu hỏi tu từ (反问句)","hỏi để khẳng định / phủ định mạnh",""]]}}},{"n":8,"i":1,"t":{"id":"tmns8-np","title":"语法 · 只要……，就 · 不是……，而是 · 正是……，因此 · 尽管……，但是 …","kind":"语法","gp":[{"ref":"zhiyao","lv":1,"h":"只要……，就 / 都 / 便……","g":"chỉ cần… là…","s":"只要 + điều kiện đủ ， + chủ ngữ + 就 / 都 / 便 + kết quả","b":["只要哪座乡镇缺乏廉价商店，沃尔玛就在哪里开业。"],"home":{"s":"dtm","t":"dtm5-np","n":5,"name":"Đọc thương mại"}},{"ref":"bushi_ershi","lv":1,"h":"不是……，而是……","g":"không phải… mà là…","s":"（主语）+ 不是 + A ，而是 + B\n变体: ……，而不是…… (Nghe nói bài 4)","b":["“你们不是在为商店讨价还价，而是在为顾客讨价还价，我们应该为顾客争取到最好的价钱。”"],"home":{"s":"dtm","t":"dtm9-np","n":9,"name":"Đọc thương mại"}},{"id":"zhengshi","lv":2,"h":"正是……，因此 / 才……","g":"chính vì…, nên…","s":"**正是（由于 / 因为）** + nguyên nhân **，（所以 / 因此）** + chủ ngữ + **才** + kết quả\n或：结果 + **，正是因为** + nguyên nhân","m":"**正是** nhấn mạnh “**chính là**” — xác định nguyên nhân then chốt. Vế sau hay có **才** (mới) để tăng sức nặng. Dùng trong kết luận phân tích.","u":"Phân tích Walmart: **正是因为坚持“天天平价”，沃尔玛才赢得了顾客**.","e":[["正是因为服务周到，这家店才吸引了大量回头客。","Chính vì phục vụ chu đáo mà cửa hàng này mới thu hút nhiều khách quay lại."],["质量和信誉，这正是我们成功的秘诀。","Chất lượng và uy tín, đó chính là bí quyết thành công của chúng tôi."]],"x":[["正是因为价格低，因此所以顾客多。","正是因为价格低，顾客才这么多。","Không chồng 因此 và 所以; dùng 才 cho tự nhiên."]],"c":"Xem 之所以……是因为 (bài 4).","b":["正是沃尔玛全方位出击，抢占了高、低档市场，因此沃尔玛取代了曾经风靡整个美国的西尔斯，成为美国零售业第一品牌。"]},{"ref":"jinguan","lv":2,"h":"尽管……，但是 / 还是 / 却……","g":"mặc dù…, nhưng vẫn…","s":"尽管 + sự thật ，（但是 / 可是） + chủ ngữ + 还是 / 仍然 / 却 / 也 + kết quả","b":["尽管沃尔玛一而再、再而三地缩减其广告开支，但在对非盈利组织和公益事业（如学校、图书馆、经济发展团体、医院、医学研究计划和环保方案等）进行捐赠时，却十分慷慨。"],"home":{"s":"dtm","t":"dtm2-np","n":2,"name":"Đọc thương mại"}},{"id":"shuangfou","lv":3,"h":"Phủ định kép: 没有……不 / 不能不 / 无不 / 不得不","g":"phủ định hai lần = khẳng định mạnh","s":"**没有（一个）……不……** (không… nào không… = tất cả đều)\n**不能不 / 不得不 / 不会不** (buộc phải, chắc chắn)\n**无不 / 无一不** (văn viết, không ai không)","m":"Hai lần phủ định tạo ra **khẳng định mạnh hơn** câu thường. 没有一个顾客不满意 mạnh hơn 顾客都满意. Mỗi dạng có sắc thái: 不能不 (bắt buộc về lý), 不会不 (chắc chắn sẽ), 无不 (văn viết, tất cả).","u":"Khen dịch vụ: **来过沃尔玛的顾客，没有一个不称赞它的服务**; Haier: **海尔的产品无不以质量取胜**.","e":[["在这里购物的顾客，没有一个不满意的。","Khách mua sắm ở đây không ai là không hài lòng."],["面对激烈的竞争，企业不能不创新。","Trước cạnh tranh gay gắt, doanh nghiệp không thể không đổi mới."]],"x":[["没有一个顾客不不满意。","没有一个顾客不满意。","Chỉ **hai** lần phủ định; ba lần thành phủ định lại."]],"c":"Link: 不得不 (HNTM viết bài 19), 非……不可 (Đọc TM bài 3).","b":["同来的人都知道，他不会不知道吧！"]}],"zh":["正是因为服务周到，这家店才吸引了大量回头客。","质量和信誉，这正是我们成功的秘诀。","正是沃尔玛全方位出击，抢占了高、低档市场，因此沃尔玛取代了曾经风靡整个美国的西尔斯，成为美国零售业第一品牌。","在这里购物的顾客，没有一个不满意的。","面对激烈的竞争，企业不能不创新。","同来的人都知道，他不会不知道吧！","只要哪座乡镇缺乏廉价商店，沃尔玛就在哪里开业。","尽管沃尔玛一而再、再而三地缩减其广告开支，但在对非盈利组织和公益事业（如学校、图书馆、经济发展团体、医院、医学研究计划和环保方案等）进行捐赠时，却十分慷慨。","“你们不是在为商店讨价还价，而是在为顾客讨价还价，我们应该为顾客争取到最好的价钱。”"],"p":["## 只要……，就 / 都 / 便…… — chỉ cần… là…","## 不是……，而是…… — không phải… mà là…","## 正是……，因此 / 才…… — chính vì…, nên…","## 尽管……，但是 / 还是 / 却…… — mặc dù…, nhưng vẫn…","## Phủ định kép: 没有……不 / 不能不 / 无不 / 不得不 — phủ định hai lần = khẳng định mạnh"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (正是 · 不 · 只要 · 尽管 · 而是)","items":[["___因为服务周到，这家店才吸引了大量回头客。","正是"],["在这里购物的顾客，没有一个___满意的。","不"],["___哪座乡镇缺乏廉价商店，沃尔玛就在哪里开业。","只要"],["___沃尔玛一而再、再而三地缩减其广告开支，但在对非盈利组织和公益事业（如学校、图书馆、经济发展团体、医院、医学研究计划和环保方案等）进行捐赠时，却十分慷慨。","尽管"],["“你们不是在为商店讨价还价，___在为顾客讨价还价，我们应该为顾客争取到最好的价钱。”","而是"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （正是……，因此 / 才……）",["正是因为价格低，因此所以顾客多。","正是因为价格低，顾客才这么多。"],1],["Câu nào đúng? （Phủ định kép: 没有……不 / 不能不 / 无不 / 不得不）",["没有一个顾客不满意。","没有一个顾客不不满意。"],0]]}],"adv":{"g":[["只要……，就 / 都 / 便……","chỉ cần… là…","只要哪座乡镇缺乏廉价商店，沃尔玛就在哪里开业。"],["不是……，而是……","không phải… mà là…","“你们不是在为商店讨价还价，而是在为顾客讨价还价，我们应该为顾客争取到最好的价钱。”"],["正是……，因此 / 才……","chính vì…, nên…","正是沃尔玛全方位出击，抢占了高、低档市场，因此沃尔玛取代了曾经风靡整个美国的西尔斯，成为美国零售业第一品牌。"],["尽管……，但是 / 还是 / 却……","mặc dù…, nhưng vẫn…","尽管沃尔玛一而再、再而三地缩减其广告开支，但在对非盈利组织和公益事业（如学校、图书馆、经济发展团体、医院、医学研究计划和环保方案等）进行捐赠时，却十分慷慨。"],["Phủ định kép: 没有……不 / 不能不 / 无不 / 不得不","phủ định hai lần = khẳng định mạnh","同来的人都知道，他不会不知道吧！"]]}}},{"n":9,"i":1,"t":{"id":"tmns9-np","title":"语法 · 可以说 · 不仅 · 如果 · 不过是……，并不是 …","kind":"语法","gp":[{"id":"keyishuo","lv":1,"h":"……，可以说……","g":"…, có thể nói…","s":"Sự thật / số liệu **，可以说** + nhận định khái quát (thường mạnh)","m":"**可以说** đứng trước một **nhận định tổng kết**, có tính đánh giá, sau khi đã đưa căn cứ. Làm cho lời đánh giá mạnh mà vẫn lịch sự (không khẳng định tuyệt đối). Có thể đứng đầu câu như thành phần chêm.","u":"Bàn về Olympic: **奥运会带来了上千亿元的投资，可以说是一次难得的商机**.","e":[["这次合作对双方都有利，可以说是一个双赢的结果。","Lần hợp tác này có lợi cho cả hai bên, có thể nói là kết quả đôi bên cùng thắng."],["可以说，没有互联网，就没有今天的电子商务。","Có thể nói, không có Internet thì không có thương mại điện tử ngày nay."]],"x":[["可以说他很好，因为他是我的朋友。","他帮了我们很多忙，可以说是我们最好的合作伙伴。","可以说 cần **căn cứ** đi trước, không chỉ cảm tính."]],"c":"Xem 插说 (Đọc TM bài 9), 可见 (Đọc TM bài 5).","b":["可以说，主办一次奥运会的效果胜过召开多次“招商会”、“推荐会”、“博览会”、“洽谈会”效果的总和。"]},{"ref":"bujin","lv":1,"h":"不仅 / 不但……，而且 / 还 / 也……","g":"không chỉ… mà còn…","s":"（chủ ngữ）+ 不仅 / 不但 + A ，而且 / 还 / 也 / 并且 + B","b":["奥运不仅是体育的盛会，而且也是经济的大舞台。","奥运也是经济，不仅因为举办奥运会本身要花钱，也会有收入，更是因为举办奥运会能带动相关产业的发展，拉动经济的增长。"],"home":{"s":"hntm","t":"tm25-np","n":25,"name":"HNTM viết"}},{"ref":"jiashe","lv":1,"h":"Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么……","g":"nếu… thì…","s":"如果 / 要是 / 假如 / 倘若 + giả thiết （的话），（那么） + chủ ngữ + 就 / 便 / 会 + kết quả","b":["如果各个企业能加快技术进步，那么就可以抓住2008年北京奥运商机，技术进步是中国企业抓住奥运商机的关键。"],"home":{"s":"dtm","t":"dtm2-np","n":2,"name":"Đọc thương mại"}},{"id":"buguoshi","lv":2,"h":"不过是……，并不是……","g":"chẳng qua là…, chứ không phải…","s":"A + **（只）不过是** + B（mức thấp）**，并不是 / 而不是** + C（mức cao hơn mà người ta nghĩ）","m":"**不过是** = chẳng qua chỉ là → **hạ thấp** mức độ, phủ nhận sự quan trọng hóa. **并** + 不 / 没 nhấn mạnh **phủ định trái với suy nghĩ thông thường**.","u":"Bàn về Olympic: **奥运经济不过是一个短期效应，并不是长期增长的动力**.","e":[["这不过是一次小小的价格调整，并不是要提价。","Đây chẳng qua là một lần điều chỉnh giá nhỏ, chứ không phải tăng giá."],["奥运会带来的繁荣不过是暂时的。","Sự phồn vinh Olympic mang lại chẳng qua chỉ là tạm thời."]],"x":[["这不过是小问题，并是不大问题。","这不过是小问题，并不是大问题。","Thứ tự đúng: **并不是**."]],"c":"Link: 不过 (Đọc TM bài 2).","b":["2008年奥运会带来的商机并不只属于中国，而是属于全世界。","其实北京不过是“近水楼台先得月”，它并不是惟一的受惠者。"]},{"id":"shui_shui","lv":3,"h":"谁……，谁就…… (đại từ nghi vấn hô ứng)","g":"ai… thì người đó…","s":"**谁** + điều kiện **，谁就** + kết quả\n（cũng: 哪儿……哪儿……、什么……什么……、怎么……怎么……）","m":"Hai đại từ nghi vấn **giống nhau** ở hai vế **chỉ cùng một đối tượng không xác định**: “ai làm X thì chính người đó được Y”. Vế sau có **就**. Không phải câu hỏi.","u":"Bàn về cạnh tranh: **谁先抓住商机，谁就能赚钱**; **哪儿的成本低，资金就流向哪儿**.","e":[["谁的产品质量好，谁就能占领市场。","Sản phẩm của ai chất lượng tốt, người đó chiếm lĩnh thị trường."],["哪儿有商机，我们就去哪儿。","Ở đâu có cơ hội kinh doanh, chúng tôi đi tới đó."]],"x":[["谁先报名，他就可以参加。","谁先报名，谁就可以参加。","Hai vế dùng **cùng một** đại từ nghi vấn."]],"c":"Liên hệ 不管 + từ nghi vấn (Đọc TM bài 10).","b":["可以这样说，谁赢得了2008年北京奥运会，谁就赢得了中国的市场。"]}],"zh":["这次合作对双方都有利，可以说是一个双赢的结果。","可以说，没有互联网，就没有今天的电子商务。","可以说，主办一次奥运会的效果胜过召开多次“招商会”、“推荐会”、“博览会”、“洽谈会”效果的总和。","这不过是一次小小的价格调整，并不是要提价。","奥运会带来的繁荣不过是暂时的。","2008年奥运会带来的商机并不只属于中国，而是属于全世界。","其实北京不过是“近水楼台先得月”，它并不是惟一的受惠者。","谁的产品质量好，谁就能占领市场。","哪儿有商机，我们就去哪儿。","可以这样说，谁赢得了2008年北京奥运会，谁就赢得了中国的市场。","奥运不仅是体育的盛会，而且也是经济的大舞台。","奥运也是经济，不仅因为举办奥运会本身要花钱，也会有收入，更是因为举办奥运会能带动相关产业的发展，拉动经济的增长。","如果各个企业能加快技术进步，那么就可以抓住2008年北京奥运商机，技术进步是中国企业抓住奥运商机的关键。"],"p":["## ……，可以说…… — …, có thể nói…","## 不仅 / 不但……，而且 / 还 / 也…… — không chỉ… mà còn…","## Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么…… — nếu… thì…","## 不过是……，并不是…… — chẳng qua là…, chứ không phải…","## 谁……，谁就…… (đại từ nghi vấn hô ứng) — ai… thì người đó…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (可以说 · 不过是 · 谁 · 不仅 · 如果)","items":[["这次合作对双方都有利，___是一个双赢的结果。","可以说"],["这___一次小小的价格调整，并不是要提价。","不过是"],["___的产品质量好，谁就能占领市场。","谁"],["奥运___是体育的盛会，而且也是经济的大舞台。","不仅"],["___各个企业能加快技术进步，那么就可以抓住2008年北京奥运商机，技术进步是中国企业抓住奥运商机的关键。","如果"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （……，可以说……）",["可以说他很好，因为他是我的朋友。","他帮了我们很多忙，可以说是我们最好的合作伙伴。"],1],["Câu nào đúng? （不过是……，并不是……）",["这不过是小问题，并不是大问题。","这不过是小问题，并是不大问题。"],0],["Câu nào đúng? （谁……，谁就…… (đại từ nghi vấn hô ứng)）",["谁先报名，他就可以参加。","谁先报名，谁就可以参加。"],1]]}],"adv":{"g":[["……，可以说……","…, có thể nói…","可以说，主办一次奥运会的效果胜过召开多次“招商会”、“推荐会”、“博览会”、“洽谈会”效果的总和。"],["不仅 / 不但……，而且 / 还 / 也……","không chỉ… mà còn…","奥运不仅是体育的盛会，而且也是经济的大舞台。"],["Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么……","nếu… thì…","如果各个企业能加快技术进步，那么就可以抓住2008年北京奥运商机，技术进步是中国企业抓住奥运商机的关键。"],["不过是……，并不是……","chẳng qua là…, chứ không phải…","2008年奥运会带来的商机并不只属于中国，而是属于全世界。"],["谁……，谁就…… (đại từ nghi vấn hô ứng)","ai… thì người đó…","可以这样说，谁赢得了2008年北京奥运会，谁就赢得了中国的市场。"]]}}},{"n":10,"i":1,"t":{"id":"tmns10-np","title":"语法 · 之一 · 不仅 · 居首位 · 占 …","kind":"语法","gp":[{"ref":"zhiyi","lv":1,"h":"……之一","g":"một trong những…","s":"（是）+ số đông + 之一: 最大的进出口公司之一、原因之一","b":["这正是米其林轮胎在市场上独领风骚的原因之一。","这正是米其林轮胎在市场上独领风骚的原因之一，米其林轮胎在中国“滚动”出了一条经营奇迹。"],"home":{"s":"hntm","t":"tm29-np","n":29,"name":"HNTM viết"}},{"ref":"bujin","lv":1,"h":"不仅 / 不但……，而且 / 还 / 也……","g":"không chỉ… mà còn…","s":"（chủ ngữ）+ 不仅 / 不但 + A ，而且 / 还 / 也 / 并且 + B","b":[],"home":{"s":"hntm","t":"tm25-np","n":25,"name":"HNTM viết"}},{"id":"jushouwei","lv":2,"h":"……居首位 / 居第……位","g":"đứng đầu / đứng thứ…","s":"A + **（在……中）居 / 位居 / 名列** + 首位 / 第×位 / 榜首","m":"**居** = ở (vị trí). Văn viết báo cáo dùng để **xếp hạng**: 居首位 (đứng đầu), 位居第二, 名列前茅 (đứng hàng đầu). Phạm vi xếp hạng dùng **在……中**.","u":"Báo cáo đầu tư nước ngoài: **在对华投资的国家和地区中，香港居首位**.","e":[["在外商投资中，制造业居首位。","Trong đầu tư nước ngoài, ngành chế tạo đứng đầu."],["该公司的销售额在全国同行中名列第三。","Doanh số công ty đứng thứ ba toàn quốc trong ngành."]],"x":[["制造业居首位第一。","制造业居首位。 / 制造业位居第一。","首位 đã là “vị trí thứ nhất”, không thêm 第一."]],"c":"Liên quan: 占 (dưới), 之一 (HNTM viết bài 29).","b":["1996年，中国在所有发展中国家中吸引外资居首位。","1996年，中国在所有发展中国家中吸引外资居首位，实际引资约423亿美元，占流入东亚地区直接投资金额比重的70%，显示中国对全球投资者的巨大的吸引力。"]},{"id":"zhan","lv":2,"h":"占……（的比重 / 百分之……）","g":"chiếm (tỷ trọng)…","s":"A + **占** + tổng thể + **的** + 百分之…… / ……% / 比重\n**A 在 B 中所占的比重**","m":"**占** = chiếm. Cấu trúc tỷ lệ: phần + 占 + tổng thể + 的 + %. Khi danh từ hóa: **所占的比重 / 份额**. Đi với 达到、超过 để nhấn mạnh.","u":"Báo cáo: **外资企业的出口额占全国出口总额的50%以上**.","e":[["外资企业的出口额占全国出口总额的一半以上。","Kim ngạch xuất khẩu của doanh nghiệp FDI chiếm hơn một nửa tổng kim ngạch cả nước."],["服务业在国民经济中所占的比重越来越大。","Tỷ trọng của ngành dịch vụ trong nền kinh tế quốc dân ngày càng lớn."]],"x":[["外资企业占百分之五十的全国出口。","外资企业的出口占全国出口总额的百分之五十。","Thứ tự: **tổng thể + 的 + %** đặt sau 占."]],"c":"Xem 分别占 (bài 7), 各占 (HNTM viết bài 29).","b":["1996年，中国在所有发展中国家中吸引外资居首位，实际引资约423亿美元，占流入东亚地区直接投资金额比重的70%，显示中国对全球投资者的巨大的吸引力。"]},{"id":"zhici2","lv":2,"h":"至此 / 截至目前","g":"đến đây, đến lúc này","s":"（Sự việc / quá trình），**至此，** + tổng kết / kết quả đạt được","m":"**至此** = đến đây (thời điểm hoặc giai đoạn vừa kể), văn viết. Dùng để **chốt một giai đoạn** và tổng kết thành quả. Đứng đầu câu, có dấu phẩy.","u":"Báo cáo thu hút đầu tư: **今年又有20家外资企业落户本市。至此，本市的外资企业已达到500家**.","e":[["合同于昨天正式签订，至此，历时半年的谈判终于结束了。","Hợp đồng chính thức ký hôm qua, đến đây cuộc đàm phán kéo dài nửa năm cuối cùng đã kết thúc."],["至此，公司已在全球设立了三十个分支机构。","Đến nay, công ty đã lập 30 chi nhánh trên toàn cầu."]],"x":[["至此明年，我们将完成任务。","到明年，我们将完成任务。","**至此** chỉ thời điểm **vừa nói tới / hiện tại**, không đi với thời gian tương lai."]],"c":"Xem 截至 (HNTM viết bài 28), 迄今 (HNTM viết bài 23).","b":["1995年，米其林集团率先抢滩登陆中国市场，与沈阳轮胎总厂合资成立了沈阳米其林轮胎有限公司，至此，米其林站稳了登陆中国的第一步；"]}],"zh":["在外商投资中，制造业居首位。","该公司的销售额在全国同行中名列第三。","1996年，中国在所有发展中国家中吸引外资居首位。","1996年，中国在所有发展中国家中吸引外资居首位，实际引资约423亿美元，占流入东亚地区直接投资金额比重的70%，显示中国对全球投资者的巨大的吸引力。","外资企业的出口额占全国出口总额的一半以上。","服务业在国民经济中所占的比重越来越大。","合同于昨天正式签订，至此，历时半年的谈判终于结束了。","至此，公司已在全球设立了三十个分支机构。","1995年，米其林集团率先抢滩登陆中国市场，与沈阳轮胎总厂合资成立了沈阳米其林轮胎有限公司，至此，米其林站稳了登陆中国的第一步；","这正是米其林轮胎在市场上独领风骚的原因之一。","这正是米其林轮胎在市场上独领风骚的原因之一，米其林轮胎在中国“滚动”出了一条经营奇迹。"],"p":["## ……之一 — một trong những…","## 不仅 / 不但……，而且 / 还 / 也…… — không chỉ… mà còn…","## ……居首位 / 居第……位 — đứng đầu / đứng thứ…","## 占……（的比重 / 百分之……） — chiếm (tỷ trọng)…","## 至此 / 截至目前 — đến đây, đến lúc này"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (居 · 占 · 至此 · 之一)","items":[["在外商投资中，制造业___首位。","居"],["外资企业的出口额___全国出口总额的一半以上。","占"],["合同于昨天正式签订，___，历时半年的谈判终于结束了。","至此"],["这正是米其林轮胎在市场上独领风骚的原因___。","之一"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （……居首位 / 居第……位）",["制造业居首位第一。","制造业居首位。 / 制造业位居第一。"],1],["Câu nào đúng? （占……（的比重 / 百分之……））",["外资企业的出口占全国出口总额的百分之五十。","外资企业占百分之五十的全国出口。"],0],["Câu nào đúng? （至此 / 截至目前）",["至此明年，我们将完成任务。","到明年，我们将完成任务。"],1]]}],"adv":{"g":[["……之一","một trong những…","这正是米其林轮胎在市场上独领风骚的原因之一。"],["不仅 / 不但……，而且 / 还 / 也……","không chỉ… mà còn…",""],["……居首位 / 居第……位","đứng đầu / đứng thứ…","1996年，中国在所有发展中国家中吸引外资居首位。"],["占……（的比重 / 百分之……）","chiếm (tỷ trọng)…","1996年，中国在所有发展中国家中吸引外资居首位，实际引资约423亿美元，占流入东亚地区直接投资金额比重的70%，显示中国对全球投资者的巨大的吸引力。"],["至此 / 截至目前","đến đây, đến lúc này","1995年，米其林集团率先抢滩登陆中国市场，与沈阳轮胎总厂合资成立了沈阳米其林轮胎有限公司，至此，米其林站稳了登陆中国的第一步；"]]}}},{"n":11,"i":1,"t":{"id":"tmns11-np","title":"语法 · 却 · 就在……的时候，……却 · 不像……那样……，而是 · 不去……，就是零 …","kind":"语法","gp":[{"id":"que","lv":1,"h":"却","g":"lại, nhưng lại (phó từ chuyển ý)","s":"Chủ ngữ + **却** + vị ngữ (trái với dự đoán / với vế trước)","m":"**却** là **phó từ** chuyển ý, đứng **sau chủ ngữ, trước động từ** (khác 但是 là liên từ đứng đầu vế). Có thể kết hợp: 但……却……. Sắc thái **bất ngờ, trái ngược**.","u":"Kể về nữ doanh nhân: **她本来可以在美国过安稳的生活，却选择了回国创业**.","e":[["她拥有名校学历，却选择从推销员做起。","Cô ấy có bằng trường danh tiếng, nhưng lại chọn bắt đầu từ nhân viên bán hàng."],["公司规模不大，利润却很高。","Quy mô công ty không lớn, lợi nhuận lại rất cao."]],"x":[["公司规模不大，却利润很高。","公司规模不大，利润却很高。","**却** đứng **sau chủ ngữ** (利润)."]],"c":"Xem câu chuyển ngoặt (Đọc TM bài 7).","b":["可是，就在事业最辉煌的时候，杨澜却急流勇退，去美国留学。"]},{"id":"jiuzai","lv":2,"h":"就在……的时候，……却……","g":"đúng vào lúc… thì lại…","s":"**就在** + thời điểm / sự kiện + **的时候 / 之际，** + chủ ngữ + **却 / 突然** + việc bất ngờ","m":"**就在** nhấn mạnh **đúng ngay thời điểm** đó. Kết hợp **却** tạo bước ngoặt bất ngờ trong câu chuyện — kỹ thuật kể chuyện hấp dẫn khi nói.","u":"Kể chuyện nữ doanh nhân: **就在事业最成功的时候，她却辞职了**.","e":[["就在公司快要上市的时候，市场却突然下跌了。","Đúng lúc công ty sắp niêm yết thì thị trường lại đột ngột đi xuống."],["就在大家都以为谈判要失败的时候，对方却让步了。","Đúng lúc mọi người tưởng đàm phán sắp thất bại thì đối phương lại nhượng bộ."]],"x":[["在她最成功的时候，她就辞职了。","就在她最成功的时候，她却辞职了。","Nhấn “đúng lúc” dùng **就在**; bất ngờ dùng **却**, không dùng 就."]],"c":"Liên hệ 却 (trên).","b":["可是，就在事业最辉煌的时候，杨澜却急流勇退，去美国留学。"]},{"id":"buxiang","lv":2,"h":"不像……那样……，而是……","g":"không như… mà…","s":"A + **不像** + B + **那样 / 那么** + đặc điểm **，而是** + đặc điểm khác","m":"So sánh **phủ định**: A không giống B ở điểm X; vế sau với **而是** nêu điểm thật của A. Dùng để **làm nổi bật cá tính** khác biệt.","u":"Mô tả nữ doanh nhân: **她不像一般女老板那样强势，而是很温和**.","e":[["这家公司不像传统企业那样层级分明，而是很扁平化。","Công ty này không phân tầng rõ rệt như doanh nghiệp truyền thống, mà rất phẳng."],["他不像别的经理那么严肃。","Anh ấy không nghiêm nghị như các giám đốc khác."]],"x":[["她不像别人一样那样强势。","她不像别人那样强势。","Chọn **那样** hoặc 一样, không dùng cả hai."]],"c":"Khẳng định: 像……一样 / 那样. So sánh: 没有……那么 (Đọc TM bài 5).","b":["所以，卓越网不像别的网站那样卖成千上万种商品，而是精挑细选，只卖几十种商品，这样库存少，配送也容易。"]},{"id":"bu_ling","lv":3,"h":"不去……，（机会）就是零","g":"không thử thì (cơ hội) bằng không","s":"**不** + hành động **，** + kết quả **就是零 / 永远不会……**\n（câu điều kiện ẩn, không có 如果）","m":"Câu **điều kiện không có liên từ** (意合): hai vế đặt cạnh nhau, quan hệ “nếu… thì” do ngữ nghĩa quyết định. Rất phổ biến trong khẩu ngữ, khẩu hiệu, lời khuyên — ngắn gọn, mạnh mẽ.","u":"Lời nữ doanh nhân: **不去尝试，成功的机会就是零**.","e":[["不去尝试，成功的机会就是零。","Không thử thì cơ hội thành công bằng không."],["不做市场调查，产品就很难卖出去。","Không khảo sát thị trường thì sản phẩm khó bán được."]],"x":[["如果不去尝试的话，那么所以机会就是零。","不去尝试，机会就是零。","Câu khẩu hiệu ngắn gọn; nếu dùng liên từ thì chỉ cần 如果……就, không thêm 所以."]],"c":"Xem câu giả thiết (Đọc TM bài 2), tỉnh lược (Đọc TM bài 7)."},{"ref":"ba","lv":3,"h":"Câu chữ “把”","g":"xử lý đối tượng: đem… làm…","s":"主语 + 把 + tân ngữ (xác định) + động từ + thành phần khác (了 / bổ ngữ / 给 / 到 / 成 / tân ngữ 2)","b":["作为一位女性，她说：“不要把自己放在一个弱者的位置上。”","李亦非抓住一切机会把MTV品牌渗透到青少年人群之中。"],"home":{"s":"dtm","t":"dtm4-np","n":4,"name":"Đọc thương mại"}}],"zh":["她拥有名校学历，却选择从推销员做起。","公司规模不大，利润却很高。","可是，就在事业最辉煌的时候，杨澜却急流勇退，去美国留学。","就在公司快要上市的时候，市场却突然下跌了。","就在大家都以为谈判要失败的时候，对方却让步了。","这家公司不像传统企业那样层级分明，而是很扁平化。","他不像别的经理那么严肃。","所以，卓越网不像别的网站那样卖成千上万种商品，而是精挑细选，只卖几十种商品，这样库存少，配送也容易。","不去尝试，成功的机会就是零。","不做市场调查，产品就很难卖出去。","作为一位女性，她说：“不要把自己放在一个弱者的位置上。”","李亦非抓住一切机会把MTV品牌渗透到青少年人群之中。"],"p":["## 却 — lại, nhưng lại (phó từ chuyển ý)","## 就在……的时候，……却…… — đúng vào lúc… thì lại…","## 不像……那样……，而是…… — không như… mà…","## 不去……，（机会）就是零 — không thử thì (cơ hội) bằng không","## Câu chữ “把” — xử lý đối tượng: đem… làm…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (却 · 就在 · 不像 · 就是零 · 把)","items":[["她拥有名校学历，___选择从推销员做起。","却"],["___公司快要上市的时候，市场却突然下跌了。","就在"],["这家公司___传统企业那样层级分明，而是很扁平化。","不像"],["不去尝试，成功的机会___。","就是零"],["作为一位女性，她说：“不要___自己放在一个弱者的位置上。”","把"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （却）",["公司规模不大，却利润很高。","公司规模不大，利润却很高。"],1],["Câu nào đúng? （就在……的时候，……却……）",["就在她最成功的时候，她却辞职了。","在她最成功的时候，她就辞职了。"],0],["Câu nào đúng? （不像……那样……，而是……）",["她不像别人一样那样强势。","她不像别人那样强势。"],1],["Câu nào đúng? （不去……，（机会）就是零）",["不去尝试，机会就是零。","如果不去尝试的话，那么所以机会就是零。"],0]]}],"adv":{"g":[["却","lại, nhưng lại (phó từ chuyển ý)","可是，就在事业最辉煌的时候，杨澜却急流勇退，去美国留学。"],["就在……的时候，……却……","đúng vào lúc… thì lại…","可是，就在事业最辉煌的时候，杨澜却急流勇退，去美国留学。"],["不像……那样……，而是……","không như… mà…","所以，卓越网不像别的网站那样卖成千上万种商品，而是精挑细选，只卖几十种商品，这样库存少，配送也容易。"],["不去……，（机会）就是零","không thử thì (cơ hội) bằng không","不去尝试，成功的机会就是零。"],["Câu chữ “把”","xử lý đối tượng: đem… làm…","作为一位女性，她说：“不要把自己放在一个弱者的位置上。”"]]}}},{"n":12,"i":1,"t":{"id":"tmns12-np","title":"语法 · 既……又 · 第一……，第二……，最后 · 只有……，才 · 对……来说 …","kind":"语法","gp":[{"ref":"binglie","lv":1,"h":"Câu đẳng lập: 既……又 / 一边……一边 / 一方面……另一方面","g":"vừa… vừa… / mặt này… mặt khác…","s":"既 + A + 又 / 也 + B (hai đặc điểm cùng có)\n一边 + V1 + 一边 + V2 (hai hành động cùng lúc)\n一方面 + A ，（另）一方面 + B (hai mặt của vấn đề)","b":["另一方面也是因为人们的环保意识增强了。","一方面，我们将加强绿色食品监督管理工作，特别是加强对获证产品的质量监管，确保绿色食品的质量和信誉。"],"home":{"s":"dtm","t":"dtm3-np","n":3,"name":"Đọc thương mại"}},{"ref":"xulie","lv":1,"h":"第一……，第二……，最后…… / 一是……，二是……","g":"thứ nhất…, thứ hai…, cuối cùng…","s":"第一 / 首先， …… 第二 / 其次， …… 第三 / 再次， …… 最后， ……\n（Văn viết gọn）一是……，二是……，三是……","b":["监督主要包括两个方面：首先是加强对企业生产过程和产品质量的监督检查；","其次是打击假冒绿色食品标志的违法行为。"],"home":{"s":"tmns","t":"tmns3-np","n":3,"name":"HNTM nghe nói"}},{"ref":"zhiyou","lv":1,"h":"只有……，才……","g":"chỉ có… mới…","s":"只有 + điều kiện duy nhất ， + chủ ngữ + 才 + kết quả","b":["只有这样，我们才能培养出健康、规范的绿色食品市场。"],"home":{"s":"dtm","t":"dtm6-np","n":6,"name":"Đọc thương mại"}},{"ref":"duilaishuo","lv":1,"h":"对（于）……来说","g":"đối với… mà nói","s":"对（于） + người / đơn vị + 来说，+ nhận định (từ góc độ người đó)","b":["对于绿色食品而言，信誉就是它的价值。"],"home":{"s":"dtm","t":"dtm6-np","n":6,"name":"Đọc thương mại"}},{"id":"eryan","lv":2,"h":"对于……而言","g":"đối với… mà nói (văn viết)","s":"**对（于）** + đối tượng + **而言，** + nhận định","m":"Dạng **văn viết** của 对……来说 (Đọc TM bài 6): nêu góc nhìn của một đối tượng. Dùng trong bài nói trang trọng, phỏng vấn, báo cáo.","u":"Đối thoại về thực phẩm xanh: **对于消费者而言，绿色食品意味着健康**.","e":[["对于中小企业而言，融资难是最大的问题。","Đối với doanh nghiệp vừa và nhỏ, khó vay vốn là vấn đề lớn nhất."],["就目前而言，市场前景还不明朗。","Xét hiện tại mà nói, triển vọng thị trường còn chưa rõ."]],"x":[["对于消费者来而言，……","对于消费者而言，…… / 对消费者来说，……","Chọn **来说** hoặc **而言**, không ghép."]],"c":"Link: 对……来说 (Đọc TM bài 6). 就……而言 = xét về….","b":["对于绿色食品而言，信誉就是它的价值。"]},{"id":"zaixia","lv":3,"h":"在……的拉动 / 推动 / 带动下","g":"dưới sức kéo / thúc đẩy của…","s":"**在** + yếu tố + **的拉动 / 推动 / 带动 / 影响下，** + kết quả kinh tế","m":"Thuật ngữ kinh tế: **拉动** (kéo theo, như tiêu dùng kéo tăng trưởng), **推动** (thúc đẩy), **带动** (dẫn dắt). Khung **在……下** (HNTM viết bài 10) làm trạng ngữ điều kiện. Rất hay gặp trong báo cáo kinh tế.","u":"Phân tích: **在消费需求的拉动下，绿色食品市场迅速扩大**.","e":[["在出口的拉动下，经济保持了较快增长。","Dưới sức kéo của xuất khẩu, kinh tế duy trì tăng trưởng khá nhanh."],["在政策的推动下，新能源汽车销量大增。","Nhờ chính sách thúc đẩy, doanh số xe năng lượng mới tăng mạnh."]],"x":[["在消费拉动，经济增长了。","在消费的拉动下，经济增长了。","Khung **在……的……下** phải đủ."]],"c":"Link: 在……下 (HNTM viết bài 10). 拉动内需 = kích cầu nội địa.","b":["在市场需求的拉动下，绿色食品开发已经具备一定规模了，近几年来，绿色食品开发一直保持在年递增50%以上的速度。"]}],"zh":["对于中小企业而言，融资难是最大的问题。","就目前而言，市场前景还不明朗。","对于绿色食品而言，信誉就是它的价值。","在出口的拉动下，经济保持了较快增长。","在政策的推动下，新能源汽车销量大增。","在市场需求的拉动下，绿色食品开发已经具备一定规模了，近几年来，绿色食品开发一直保持在年递增50%以上的速度。","另一方面也是因为人们的环保意识增强了。","一方面，我们将加强绿色食品监督管理工作，特别是加强对获证产品的质量监管，确保绿色食品的质量和信誉。","监督主要包括两个方面：首先是加强对企业生产过程和产品质量的监督检查；","其次是打击假冒绿色食品标志的违法行为。","只有这样，我们才能培养出健康、规范的绿色食品市场。"],"p":["## Câu đẳng lập: 既……又 / 一边……一边 / 一方面……另一方面 — vừa… vừa… / mặt này… mặt khác…","## 第一……，第二……，最后…… / 一是……，二是…… — thứ nhất…, thứ hai…, cuối cùng…","## 只有……，才…… — chỉ có… mới…","## 对（于）……来说 — đối với… mà nói","## 对于……而言 — đối với… mà nói (văn viết)","## 在……的拉动 / 推动 / 带动下 — dưới sức kéo / thúc đẩy của…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (而言 · 拉动 · 首先 · 只有)","items":[["对于中小企业___，融资难是最大的问题。","而言"],["在出口的___下，经济保持了较快增长。","拉动"],["监督主要包括两个方面：___是加强对企业生产过程和产品质量的监督检查；","首先"],["___这样，我们才能培养出健康、规范的绿色食品市场。","只有"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （对于……而言）",["对于消费者来而言，……","对于消费者而言，…… / 对消费者来说，……"],1],["Câu nào đúng? （在……的拉动 / 推动 / 带动下）",["在消费的拉动下，经济增长了。","在消费拉动，经济增长了。"],0]]}],"adv":{"g":[["Câu đẳng lập: 既……又 / 一边……一边 / 一方面……另一方面","vừa… vừa… / mặt này… mặt khác…","另一方面也是因为人们的环保意识增强了。"],["第一……，第二……，最后…… / 一是……，二是……","thứ nhất…, thứ hai…, cuối cùng…","监督主要包括两个方面：首先是加强对企业生产过程和产品质量的监督检查；"],["只有……，才……","chỉ có… mới…","只有这样，我们才能培养出健康、规范的绿色食品市场。"],["对（于）……来说","đối với… mà nói","对于绿色食品而言，信誉就是它的价值。"],["对于……而言","đối với… mà nói (văn viết)","对于绿色食品而言，信誉就是它的价值。"],["在……的拉动 / 推动 / 带动下","dưới sức kéo / thúc đẩy của…","在市场需求的拉动下，绿色食品开发已经具备一定规模了，近几年来，绿色食品开发一直保持在年递增50%以上的速度。"]]}}},{"n":13,"i":1,"t":{"id":"tmns13-np","title":"语法 · 所谓……，就是 · 透支、刷卡、还款、贷款 · 非……不可 · Câu tự hỏi tự đáp","kind":"语法","gp":[{"id":"suowei","lv":2,"h":"所谓……，就是……","g":"cái gọi là… chính là…","s":"**所谓** + thuật ngữ **，就是 / 是指** + định nghĩa\n或：giải thích **，这就是所谓的** + thuật ngữ","m":"**所谓** = cái được gọi là. Dùng để **định nghĩa, giải thích thuật ngữ** — rất cần khi thuyết trình kinh tế. Hai hướng: nêu thuật ngữ trước rồi định nghĩa, hoặc mô tả trước rồi “gắn nhãn” bằng **这就是所谓的……**. Văn viết: **所谓……，系指……**. Lưu ý: 所谓 đôi khi mang ý **mỉa mai** (“cái gọi là…”).","u":"Giải thích thẻ tín dụng: **所谓透支，就是先消费后还款**; **先花明天的钱，这就是所谓的超前消费**.","e":[["所谓信用卡，就是银行发给信用良好的客户的一种消费凭证。","Cái gọi là thẻ tín dụng chính là một loại chứng từ tiêu dùng ngân hàng cấp cho khách hàng có tín dụng tốt."],["先消费，后还款，这就是所谓的透支。","Tiêu trước trả sau, đó chính là cái gọi là thấu chi."]],"x":[["所谓透支就是的先消费。","所谓透支，就是先消费后还款。","Sau **就是** là định nghĩa trực tiếp, không thêm 的."]],"c":"Thuyết trình: dùng 所谓 để mở thuật ngữ, rồi 比如说 (bài 6) để minh họa.","b":["所谓信用卡就是“先享受，后付款”，银行通过这笔原先应付而未付的钱，赚取更多的利息。","所谓免息还款期，为银行记账日到规定付款截止日之间的时间，在这段时间里，持卡人不用交纳利息。","补救之道就是多申请几张信用卡，将各卡的结账日错开，如此一来，“免息消费日”就可以多几天，增加刷卡消费的弹性，这就是所谓的“聪明的分散刷卡策略”。"]},{"id":"dongbin","lv":2,"h":"Cụm động – tân ngữ: 透支、刷卡、还款、贷款","g":"động từ ly hợp trong ngân hàng","s":"Động từ ly hợp (离合词): **刷** + 卡 → 刷了三次卡；**还** + 款 → 还了款；**贷** + 款 → 贷了一笔款\nKhông mang thêm tân ngữ: ✗ 刷卡商店 → ✓ 在商店刷卡","m":"Nhiều từ ngân hàng là **động từ ly hợp** (动宾式): bản thân đã có tân ngữ bên trong, nên **không mang thêm tân ngữ**, và khi thêm 了 / số lần / định ngữ thì **tách** ra: 见了面、刷了两次卡、贷了五十万的款.","u":"Hội thoại ngân hàng: **您可以在全国任何一家商场刷卡消费**; **请按时还款，以免影响信用记录**.","e":[["他上个月刷了五次卡，一共消费了八千元。","Tháng trước anh ấy quẹt thẻ năm lần, tiêu tổng cộng 8.000 tệ."],["公司向银行贷了一笔款。","Công ty vay ngân hàng một khoản."]],"x":[["我们见面客户了。","我们跟客户见面了。","**见面** là động từ ly hợp, đối tượng đặt trước bằng 跟."],["我刷卡了三次。","我刷了三次卡。","Số lần chen **giữa** động từ và tân ngữ."]],"c":"Từ ly hợp hay gặp trong kinh tế: 投资 không ly hợp, nhưng 投保、签字、开会、出差、加班、请假 là ly hợp.","b":["因为信用卡最怕丢，用信用卡付款时，收款员只是核对一下签名，没有密码。","这种方法促使消费者集中火力只用一张信用卡付款，正好和“分散刷卡策略”相反。","所谓信用卡就是“先享受，后付款”，银行通过这笔原先应付而未付的钱，赚取更多的利息。"]},{"ref":"feibuke","lv":2,"h":"非……不可","g":"nhất định phải…, không… không được","s":"主语 + 非 + động từ / danh từ + 不可 / 不行 / 不成","b":["一旦信用卡被盗或丢失，非要到银行进行书面挂失，手续繁琐，而在挂失生效之前，信用卡如果被非法提现或冒用，银行不承担责任，这样将无法保证持卡人的安全。"],"home":{"s":"dtm","t":"dtm3-np","n":3,"name":"Đọc thương mại"}},{"id":"shewen","lv":3,"h":"Câu tự hỏi tự đáp (设问)","g":"đặt câu hỏi rồi tự trả lời","s":"……**呢？** + （**当然 / 原来 / 答案是**）+ câu trả lời","m":"**设问** là biện pháp tu từ: người nói **tự đặt câu hỏi** để thu hút chú ý, rồi **tự trả lời** ngay. Khác 反问 (Đọc TM bài 6) là câu hỏi không cần trả lời. Rất hiệu quả trong thuyết trình, quảng cáo.","u":"Thuyết trình về thẻ tín dụng: **信用卡为什么这么受欢迎呢？原因很简单：方便、安全**.","e":[["银行为什么愿意给我们透支呢？当然是为了赚利息。","Vì sao ngân hàng sẵn lòng cho chúng ta thấu chi? Đương nhiên là để kiếm lãi."],["怎样才能避免信用卡欠债呢？关键是要控制消费。","Làm sao tránh nợ thẻ tín dụng? Then chốt là kiểm soát chi tiêu."]],"x":[["信用卡有什么好处呢？我们下次再说吧。","信用卡有什么好处呢？第一，方便；第二，安全。","设问 phải **tự trả lời** ngay sau câu hỏi."]],"c":"Link: 反问句 (Đọc TM bài 6)."}],"zh":["所谓信用卡，就是银行发给信用良好的客户的一种消费凭证。","先消费，后还款，这就是所谓的透支。","所谓信用卡就是“先享受，后付款”，银行通过这笔原先应付而未付的钱，赚取更多的利息。","所谓免息还款期，为银行记账日到规定付款截止日之间的时间，在这段时间里，持卡人不用交纳利息。","补救之道就是多申请几张信用卡，将各卡的结账日错开，如此一来，“免息消费日”就可以多几天，增加刷卡消费的弹性，这就是所谓的“聪明的分散刷卡策略”。","银行为什么愿意给我们透支呢？当然是为了赚利息。","怎样才能避免信用卡欠债呢？关键是要控制消费。","他上个月刷了五次卡，一共消费了八千元。","公司向银行贷了一笔款。","因为信用卡最怕丢，用信用卡付款时，收款员只是核对一下签名，没有密码。","这种方法促使消费者集中火力只用一张信用卡付款，正好和“分散刷卡策略”相反。","一旦信用卡被盗或丢失，非要到银行进行书面挂失，手续繁琐，而在挂失生效之前，信用卡如果被非法提现或冒用，银行不承担责任，这样将无法保证持卡人的安全。"],"p":["## 所谓……，就是…… — cái gọi là… chính là…","## Cụm động – tân ngữ: 透支、刷卡、还款、贷款 — động từ ly hợp trong ngân hàng","## 非……不可 — nhất định phải…, không… không được","## Câu tự hỏi tự đáp (设问) — đặt câu hỏi rồi tự trả lời"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (所谓 · 呢 · 非)","items":[["___信用卡，就是银行发给信用良好的客户的一种消费凭证。","所谓"],["银行为什么愿意给我们透支___？当然是为了赚利息。","呢"],["一旦信用卡被盗或丢失，___要到银行进行书面挂失，手续繁琐，而在挂失生效之前，信用卡如果被非法提现或冒用，银行不承担责任，这样将无法保证持卡人的安全。","非"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （所谓……，就是……）",["所谓透支就是的先消费。","所谓透支，就是先消费后还款。"],1],["Câu nào đúng? （Câu tự hỏi tự đáp (设问)）",["信用卡有什么好处呢？第一，方便；第二，安全。","信用卡有什么好处呢？我们下次再说吧。"],0],["Câu nào đúng? （Cụm động – tân ngữ: 透支、刷卡、还款、贷款）",["我们见面客户了。","我们跟客户见面了。"],1],["Câu nào đúng? （Cụm động – tân ngữ: 透支、刷卡、还款、贷款）",["我刷了三次卡。","我刷卡了三次。"],0]]}],"adv":{"g":[["所谓……，就是……","cái gọi là… chính là…","所谓信用卡就是“先享受，后付款”，银行通过这笔原先应付而未付的钱，赚取更多的利息。"],["Cụm động – tân ngữ: 透支、刷卡、还款、贷款","động từ ly hợp trong ngân hàng","因为信用卡最怕丢，用信用卡付款时，收款员只是核对一下签名，没有密码。"],["非……不可","nhất định phải…, không… không được","一旦信用卡被盗或丢失，非要到银行进行书面挂失，手续繁琐，而在挂失生效之前，信用卡如果被非法提现或冒用，银行不承担责任，这样将无法保证持卡人的安全。"],["Câu tự hỏi tự đáp (设问)","đặt câu hỏi rồi tự trả lời","银行为什么愿意给我们透支呢？当然是为了赚利息。"]]}}},{"n":14,"i":1,"t":{"id":"tmns14-np","title":"语法 · 如果 · A 是 B · 一旦……，就 · 除非 …","kind":"语法","gp":[{"ref":"jiashe","lv":1,"h":"Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么……","g":"nếu… thì…","s":"如果 / 要是 / 假如 / 倘若 + giả thiết （的话），（那么） + chủ ngữ + 就 / 便 / 会 + kết quả","b":["如果僵局无法打破，有更好的选择将会提高你的判断能力。","如果最后期限已经被其他人确定，要看看能否改变它。"],"home":{"s":"dtm","t":"dtm2-np","n":2,"name":"Đọc thương mại"}},{"id":"biyu","lv":2,"h":"So sánh ẩn dụ: A 是 B / A 像 B 一样 / 好比","g":"nói ví von","s":"A + **是** + B (ẩn dụ: 谈判是一场战争)\nA + **像 / 好像 / 好比** + B + **（一样）** (so sánh rõ)","m":"**Ẩn dụ** (隐喻) dùng **是**: nói A chính là B — mạnh, cô đọng. **So sánh rõ** (明喻) dùng **像 / 好比 / 如同 + 一样**. Trong thuyết trình kinh tế, ví von giúp khái niệm trừu tượng dễ hiểu.","u":"Kỹ năng đàm phán: **谈判是一门艺术**; **市场就像大海，有风平浪静的时候，也有惊涛骇浪的时候**.","e":[["商场如战场，谈判好比打仗。","Thương trường như chiến trường, đàm phán ví như đánh trận."],["好的谈判者像一位优秀的演员。","Nhà đàm phán giỏi giống như một diễn viên xuất sắc."]],"x":[["谈判是像一场战争。","谈判是一场战争。 / 谈判像一场战争。","Chọn **是** (ẩn dụ) hoặc **像** (so sánh), không ghép."]],"c":"Nghe nói bài 10 có bài luyện 比喻 (ví von) trong ngôn ngữ kinh tế.","b":["谈判是一场没有硝烟的战争，需要斗智斗勇。","管理是一门艺术。"]},{"ref":"yidan","lv":2,"h":"一旦……，就 / 将……","g":"một khi… thì…","s":"一旦 + sự việc (thường bất ngờ / quan trọng) ， + chủ ngữ + 就 / 便 / 将 + kết quả","b":["一旦你为自己找出更好的选择方式，你以前认定的“最好买卖”可能就不那么十全十美了，你也就知道什么时候该走开了。"],"home":{"s":"dtm","t":"dtm8-np","n":8,"name":"Đọc thương mại"}},{"id":"chufei","lv":3,"h":"除非……，（否则 / 不然）……","g":"trừ phi…, (nếu không thì)…","s":"① **除非** + điều kiện duy nhất **，否则 / 不然** + 不…… (hậu quả)\n② **除非** + điều kiện **，才** + kết quả\n③ **不要 / 不会** + A **，除非** + điều kiện","m":"**除非** nêu **điều kiện duy nhất** (giống 只有), nhưng vế sau thường nói **hậu quả khi điều kiện không xảy ra** (否则……不). Câu ③ đặt 除非 ở cuối như một ngoại lệ: “đừng làm A, trừ khi…”. Đây là điểm khó vì phải xử lý phủ định chính xác.","u":"Kỹ năng đàm phán: **不要先报价，除非对方坚持要你先开口**; **除非对方让步，否则我们不签合同**.","e":[["除非对方降价，否则我们不会签合同。","Trừ phi đối phương giảm giá, nếu không chúng tôi sẽ không ký hợp đồng."],["不要轻易让步，除非你能得到相应的回报。","Đừng dễ dàng nhượng bộ, trừ khi bạn nhận được sự đền đáp tương ứng."]],"x":[["除非对方降价，我们就签合同。","除非对方降价，我们才签合同。 / 除非对方降价，否则我们不签合同。","除非 đi với **才** hoặc **否则……不**, không đi với 就."]],"c":"Link: 只有……才 (Đọc TM bài 6), 否则 (HNTM viết bài 24).","b":["所以，不要泄露你活动的最后期限，除非这样做对你有利。"]},{"ref":"yibian","lv":3,"h":"……，以便……","g":"…, để (tiện cho)…","s":"Vế 1 (việc làm trước) ，以便 + vế 2 (mục đích làm cho dễ dàng)","b":["一下飞机，日本公司的人就很客气地问他什么时候返回美国，说：“我们需要了解这一点，以便安排车子送你去机场。”"],"home":{"s":"hntm","t":"tm1-np","n":1,"name":"HNTM viết"}}],"zh":["除非对方降价，否则我们不会签合同。","不要轻易让步，除非你能得到相应的回报。","所以，不要泄露你活动的最后期限，除非这样做对你有利。","商场如战场，谈判好比打仗。","好的谈判者像一位优秀的演员。","谈判是一场没有硝烟的战争，需要斗智斗勇。","管理是一门艺术。","一下飞机，日本公司的人就很客气地问他什么时候返回美国，说：“我们需要了解这一点，以便安排车子送你去机场。”","一旦你为自己找出更好的选择方式，你以前认定的“最好买卖”可能就不那么十全十美了，你也就知道什么时候该走开了。","如果僵局无法打破，有更好的选择将会提高你的判断能力。","如果最后期限已经被其他人确定，要看看能否改变它。"],"p":["## Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么…… — nếu… thì…","## So sánh ẩn dụ: A 是 B / A 像 B 一样 / 好比 — nói ví von","## 一旦……，就 / 将…… — một khi… thì…","## 除非……，（否则 / 不然）…… — trừ phi…, (nếu không thì)…","## ……，以便…… — …, để (tiện cho)…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (除非 · 好比 · 以便 · 一旦 · 如果)","items":[["___对方降价，否则我们不会签合同。","除非"],["商场如战场，谈判___打仗。","好比"],["一下飞机，日本公司的人就很客气地问他什么时候返回美国，说：“我们需要了解这一点，___安排车子送你去机场。”","以便"],["___你为自己找出更好的选择方式，你以前认定的“最好买卖”可能就不那么十全十美了，你也就知道什么时候该走开了。","一旦"],["___僵局无法打破，有更好的选择将会提高你的判断能力。","如果"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （除非……，（否则 / 不然）……）",["除非对方降价，我们就签合同。","除非对方降价，我们才签合同。 / 除非对方降价，否则我们不签合同。"],1],["Câu nào đúng? （So sánh ẩn dụ: A 是 B / A 像 B 一样 / 好比）",["谈判是一场战争。 / 谈判像一场战争。","谈判是像一场战争。"],0]]}],"adv":{"g":[["Câu giả thiết: 如果 / 要是 / 假如……（的话），就 / 那么……","nếu… thì…","如果僵局无法打破，有更好的选择将会提高你的判断能力。"],["So sánh ẩn dụ: A 是 B / A 像 B 一样 / 好比","nói ví von","谈判是一场没有硝烟的战争，需要斗智斗勇。"],["一旦……，就 / 将……","một khi… thì…","一旦你为自己找出更好的选择方式，你以前认定的“最好买卖”可能就不那么十全十美了，你也就知道什么时候该走开了。"],["除非……，（否则 / 不然）……","trừ phi…, (nếu không thì)…","所以，不要泄露你活动的最后期限，除非这样做对你有利。"],["……，以便……","…, để (tiện cho)…","一下飞机，日本公司的人就很客气地问他什么时候返回美国，说：“我们需要了解这一点，以便安排车子送你去机场。”"]]}}},{"n":15,"i":1,"t":{"id":"tmns15-np","title":"语法 · 当……时 · 之一 · 既是……，同时也是 · Điệp cấu trúc","kind":"语法","gp":[{"id":"dangshi","lv":1,"h":"当……（的）时（候），……","g":"khi…","s":"**当** + sự việc + **（的）时候 / 时，** + vế chính\n**每当**…… (mỗi khi, Đọc TM bài 4)","m":"**当……时** làm trạng ngữ thời gian, nhấn mạnh **thời điểm một sự việc xảy ra**. Văn viết dùng **当……时**; khẩu ngữ hay bỏ 当. Có thể đi với **立刻 / 马上** ở vế sau để nói phản ứng ngay.","u":"Thuyết trình về Expo: **当上海获得2010年世博会主办权时，整个城市立刻沸腾了**.","e":[["当消息传来时，大家立刻欢呼起来。","Khi tin truyền đến, mọi người lập tức reo hò."],["当市场需求下降的时候，企业应该及时调整生产。","Khi nhu cầu thị trường giảm, doanh nghiệp nên kịp thời điều chỉnh sản xuất."]],"x":[["当我到北京，……","当我到北京的时候，……","Khung **当……时（候）** phải đóng đủ."]],"c":"Mở rộng: 每当 (Đọc TM bài 4), 就在……的时候 (bài 11)."},{"ref":"zhiyi","lv":1,"h":"……之一","g":"một trong những…","s":"（是）+ số đông + 之一: 最大的进出口公司之一、原因之一","b":[],"home":{"s":"hntm","t":"tm29-np","n":29,"name":"HNTM viết"}},{"id":"jishi_ye","lv":2,"h":"既是……，同时也是……","g":"vừa là…, đồng thời cũng là…","s":"A + **既是** + B **，（同时）也是 / 又是** + C","m":"Nêu **hai vai trò / hai tính chất** cùng lúc của một đối tượng. **同时** nhấn mạnh tính song hành. Khác 既……又…… (Đọc TM bài 3) ở chỗ sau 是 là **danh từ** (vai trò), còn 既……又 thường đi với tính từ / động từ.","u":"Expo: **世博会既是一次展示成就的盛会，同时也是一个巨大的商机**.","e":[["世博会既是文化盛会，同时也是经济盛会。","Expo vừa là ngày hội văn hóa, đồng thời cũng là ngày hội kinh tế."],["他既是公司的创始人，又是最大的股东。","Ông ấy vừa là người sáng lập công ty, lại là cổ đông lớn nhất."]],"x":[["世博会既是盛会，也商机。","世博会既是盛会，也是商机。","Vế sau cũng cần **是**."]],"c":"Link: 既……又 (Đọc TM bài 3)."},{"id":"paibi","lv":3,"h":"Điệp cấu trúc (排比)","g":"ba vế song song tăng sức thuyết phục","s":"（≥ 3 vế）cấu trúc giống nhau, ý tăng dần：**……是……的……，是……的……，更是……的……**","m":"**排比** là biện pháp tu từ: ba (hoặc hơn) cụm / câu có **cấu trúc giống nhau, ý cùng hướng**, thường **tăng dần** về mức độ. Tạo nhịp mạnh, khí thế — rất hay dùng trong diễn văn, kết thúc thuyết trình.","u":"Diễn văn Expo: **世博会是展示的舞台，是交流的桥梁，更是合作的纽带**; nâng ly (HNTM viết bài 12): 为……，为……，干杯！","e":[["诚信是企业的生命，是发展的基础，更是成功的保证。","Chữ tín là sinh mệnh của doanh nghiệp, là nền tảng của phát triển, càng là bảo đảm của thành công."],["我们要有新的观念、新的技术、新的管理。","Chúng ta cần có quan niệm mới, công nghệ mới, quản lý mới."]],"x":[["诚信是生命，基础，也很保证成功。","诚信是企业的生命，是发展的基础，更是成功的保证。","Các vế **cùng cấu trúc**, tăng dần (更是…)."]],"c":"Link: 为……为……干杯 (HNTM viết bài 12), 四字格 (HNTM viết bài 11)."}],"zh":["当消息传来时，大家立刻欢呼起来。","当市场需求下降的时候，企业应该及时调整生产。","世博会既是文化盛会，同时也是经济盛会。","他既是公司的创始人，又是最大的股东。","诚信是企业的生命，是发展的基础，更是成功的保证。","我们要有新的观念、新的技术、新的管理。"],"p":["## 当……（的）时（候），…… — khi…","## ……之一 — một trong những…","## 既是……，同时也是…… — vừa là…, đồng thời cũng là…","## Điệp cấu trúc (排比) — ba vế song song tăng sức thuyết phục"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (当 · 既是 · 更是)","items":[["___消息传来时，大家立刻欢呼起来。","当"],["世博会___文化盛会，同时也是经济盛会。","既是"],["诚信是企业的生命，是发展的基础，___成功的保证。","更是"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （当……（的）时（候），……）",["当我到北京，……","当我到北京的时候，……"],1],["Câu nào đúng? （既是……，同时也是……）",["世博会既是盛会，也是商机。","世博会既是盛会，也商机。"],0],["Câu nào đúng? （Điệp cấu trúc (排比)）",["诚信是生命，基础，也很保证成功。","诚信是企业的生命，是发展的基础，更是成功的保证。"],1]]}],"adv":{"g":[["当……（的）时（候），……","khi…","当消息传来时，大家立刻欢呼起来。"],["……之一","một trong những…",""],["既是……，同时也是……","vừa là…, đồng thời cũng là…","世博会既是文化盛会，同时也是经济盛会。"],["Điệp cấu trúc (排比)","ba vế song song tăng sức thuyết phục","诚信是企业的生命，是发展的基础，更是成功的保证。"]]}}},{"n":16,"i":1,"t":{"id":"tmns16-np","title":"语法 · 随着 · 受……影响 · 预计 · 增长了 …","kind":"语法","gp":[{"id":"suizhe","lv":1,"h":"随着……，……","g":"cùng với (sự)…, …","s":"**随着** + sự thay đổi (经济的发展、技术的进步) **，** + chủ ngữ + thay đổi tương ứng","m":"**随着** nêu **sự biến đổi làm nền**, vế sau là biến đổi đi kèm. Sau 随着 thường là **cụm danh từ có “的”** chỉ quá trình (……的发展 / 提高 / 变化). Vế sau phải có **chủ ngữ** riêng.","u":"Thảo luận kinh tế thế giới: **随着经济全球化的发展，各国经济的联系越来越紧密**.","e":[["随着互联网的普及，网上购物越来越流行。","Cùng với sự phổ cập Internet, mua sắm trực tuyến ngày càng thịnh hành."],["随着人民收入的提高，消费结构发生了很大变化。","Cùng với thu nhập người dân tăng, cơ cấu tiêu dùng thay đổi lớn."]],"x":[["随着经济的发展，使人们的生活提高了。","随着经济的发展，人们的生活水平提高了。","Không thêm **使** (lỗi mất chủ ngữ, xem HNTM viết bài 10); 生活 đi với 水平提高."]],"c":"Link: 由于……，使…… (HNTM viết bài 10), 日益 (HNTM viết bài 24)."},{"id":"shou_yingxiang","lv":2,"h":"受……（的）影响 / 冲击","g":"chịu ảnh hưởng / tác động của…","s":"A + **受（到）** + B + **（的）影响 / 冲击 / 制约**\n**受……影响，** + kết quả","m":"**受** = chịu, nhận (bị động không cần 被). Cụm **受……影响** làm vị ngữ hoặc làm trạng ngữ đầu câu nêu nguyên nhân khách quan. 冲击 = tác động mạnh, cú sốc; 制约 = kìm hãm.","u":"Thảo luận kinh tế 2002: **受美国经济衰退的影响，全球贸易增长放缓**.","e":[["受金融危机的影响，许多企业出现了亏损。","Chịu ảnh hưởng của khủng hoảng tài chính, nhiều doanh nghiệp bị lỗ."],["出口受到汇率变化的严重冲击。","Xuất khẩu chịu tác động nghiêm trọng của biến động tỷ giá."]],"x":[["被金融危机影响，……","受金融危机影响，……","Ảnh hưởng khách quan dùng **受**, tự nhiên hơn 被."]],"c":"Link: câu bị động (HNTM viết bài 26)."},{"id":"yuji","lv":2,"h":"预计 / 估计……","g":"dự kiến / ước tính…","s":"**预计 / 预测 / 估计** + （thời gian）+ mệnh đề có số liệu tương lai\n（主语）+ **预计** + 将 / 会……","m":"**预计** = dự kiến (dựa trên tính toán, kế hoạch), văn viết, dùng trong báo cáo, tin kinh tế. **估计** = ước chừng (khẩu ngữ hơn). **预测** = dự báo (của chuyên gia, tổ chức). Tân ngữ là mệnh đề, thường có **将 / 会**.","u":"Thảo luận triển vọng: **国际货币基金组织预计，明年世界经济将增长3%**.","e":[["预计今年全年销售额将突破十亿元。","Dự kiến doanh số cả năm nay sẽ vượt một tỷ tệ."],["专家预测，明年油价还会上涨。","Chuyên gia dự báo năm sau giá dầu còn tăng."]],"x":[["预计去年增长了百分之五。","据统计，去年增长了百分之五。","**预计** chỉ dùng cho **tương lai**; số liệu đã có dùng 据统计."]],"c":"Link: 必将 (HNTM viết bài 5), 据 (HNTM viết bài 14).","b":["日本经济衰退的幅度比预测的低，以内需为主的经济也开始复苏。","专家估计，2004年以前，美国的失业率将徘徊在5.5%到6.5%之间，很难回落到6%这条“心理警戒线”以下。"]},{"ref":"zengzhang","lv":2,"h":"Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平","g":"tăng thêm / tăng lên tới / so cùng kỳ / ngang bằng","s":"增长 / 增加 / 上升 + 了 + phần tăng (增长了20%)\n增长 / 增加 + 到 / 至 + con số cuối (增长到一亿)\n比上季度 / 同比 / 环比 + 增长……\n与……持平 (ngang bằng)\n翻了一番 (gấp đôi)","b":["排在第二位的摩托罗拉，手机销量与上年同一季度相比减少了0.8%。","现在油价并未超出欧佩克制定的基准价位，所以欧佩克不会增加原油产量。"],"home":{"s":"tmns","t":"tmns7-np","n":7,"name":"HNTM nghe nói"}},{"id":"yuqi_buru","lv":3,"h":"与其……，不如……","g":"thay vì…, chi bằng…","s":"**与其** + phương án A (bị loại) **，（还）不如 / 倒不如 / 宁可** + phương án B (được chọn)","m":"Câu **lựa chọn có thiên hướng**: so sánh hai phương án, **bỏ A chọn B**. Phương án sau 与其 là cái **bị đánh giá thấp**. Văn viết và khẩu ngữ đều dùng. Rất hữu ích khi tư vấn, đề xuất chiến lược.","u":"Thảo luận cạnh tranh: **与其在价格上竞争，不如在质量和服务上下功夫**.","e":[["与其降价促销，不如提高产品质量。","Thay vì giảm giá khuyến mãi, chi bằng nâng cao chất lượng sản phẩm."],["与其等待机会，不如主动去开拓市场。","Thay vì chờ cơ hội, chi bằng chủ động đi mở thị trường."]],"x":[["降价不好，与其提高质量，不如降价。","降价不好，与其降价，不如提高质量。","Phương án **được chọn** đặt sau **不如**; phương án bị bỏ đặt sau 与其."]],"c":"Link: 不是……而是 (Đọc TM bài 9), 宁可……也不 (thà… chứ không)."}],"zh":["随着互联网的普及，网上购物越来越流行。","随着人民收入的提高，消费结构发生了很大变化。","受金融危机的影响，许多企业出现了亏损。","出口受到汇率变化的严重冲击。","预计今年全年销售额将突破十亿元。","专家预测，明年油价还会上涨。","日本经济衰退的幅度比预测的低，以内需为主的经济也开始复苏。","专家估计，2004年以前，美国的失业率将徘徊在5.5%到6.5%之间，很难回落到6%这条“心理警戒线”以下。","与其降价促销，不如提高产品质量。","与其等待机会，不如主动去开拓市场。","排在第二位的摩托罗拉，手机销量与上年同一季度相比减少了0.8%。","现在油价并未超出欧佩克制定的基准价位，所以欧佩克不会增加原油产量。"],"p":["## 随着……，…… — cùng với (sự)…, …","## 受……（的）影响 / 冲击 — chịu ảnh hưởng / tác động của…","## 预计 / 估计…… — dự kiến / ước tính…","## Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平 — tăng thêm / tăng lên tới / so cùng kỳ / ngang bằng","## 与其……，不如…… — thay vì…, chi bằng…"],"notes":[],"ex":[{"t":"fill","q":"Điền từ còn thiếu (随着 · 受 · 预计 · 与其)","items":[["___互联网的普及，网上购物越来越流行。","随着"],["___金融危机的影响，许多企业出现了亏损。","受"],["___今年全年销售额将突破十亿元。","预计"],["___降价促销，不如提高产品质量。","与其"]]},{"t":"mc","q":"Chọn câu đúng (mỗi câu một điểm ngữ pháp trong bài)","items":[["Câu nào đúng? （随着……，……）",["随着经济的发展，使人们的生活提高了。","随着经济的发展，人们的生活水平提高了。"],1],["Câu nào đúng? （受……（的）影响 / 冲击）",["受金融危机影响，……","被金融危机影响，……"],0],["Câu nào đúng? （预计 / 估计……）",["预计去年增长了百分之五。","据统计，去年增长了百分之五。"],1],["Câu nào đúng? （与其……，不如……）",["降价不好，与其降价，不如提高质量。","降价不好，与其提高质量，不如降价。"],0]]}],"adv":{"g":[["随着……，……","cùng với (sự)…, …","随着互联网的普及，网上购物越来越流行。"],["受……（的）影响 / 冲击","chịu ảnh hưởng / tác động của…","受金融危机的影响，许多企业出现了亏损。"],["预计 / 估计……","dự kiến / ước tính…","日本经济衰退的幅度比预测的低，以内需为主的经济也开始复苏。"],["Số liệu tăng giảm: 增长了 / 增长到 / 同比 / 环比 / 持平","tăng thêm / tăng lên tới / so cùng kỳ / ngang bằng","排在第二位的摩托罗拉，手机销量与上年同一季度相比减少了0.8%。"],["与其……，不如……","thay vì…, chi bằng…","与其降价促销，不如提高产品质量。"]]}}}]);
